window.DL_SIGNS=[{"id":"A1","cat":"A","sv":"Varning för farlig kurva","en":"","svText":"Märket anger en farlig kurva samt kurvans riktning.","enText":"","tip":"","kw":[],"img":"A1-1","variants":[{"key":"A1-2","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-farlig-kurva/","related":[]},{"id":"A2","cat":"A","sv":"Varning för flera farliga kurvor","en":"","svText":"Märket anger flera farliga kurvor samt den första farliga kurvans riktning.","enText":"","tip":"","kw":[],"img":"A2-1","variants":[{"key":"A2-2","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-flera-farliga-kurvor/","related":[]},{"id":"A3","cat":"A","sv":"Varning för nedförslutning","en":"","svText":"Märket anger brant nedförslutning. Siffran anger lutningen i procent och är anpassad till förhållandena på platsen.","enText":"","tip":"","kw":[],"img":"A3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-nedforslutning/","related":[]},{"id":"A4","cat":"A","sv":"Varning för stigning","en":"","svText":"Märket anger kraftig stigning. Siffran anger stigningen i procent och är anpassad till förhållandena på platsen.","enText":"","tip":"","kw":[],"img":"A4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-stigning/","related":[]},{"id":"A5","cat":"A","sv":"Varning för avsmalnande väg","en":"","svText":"","enText":"","tip":"","kw":[],"img":"A5-1","variants":[{"key":"A5-2","en":""},{"key":"A5-3","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-avsmalnande-vag/","related":[]},{"id":"A6","cat":"A","sv":"Varning för bro","en":"","svText":"Märket anger en öppningsbar bro.","enText":"","tip":"","kw":[],"img":"A6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-bro/","related":[]},{"id":"A7","cat":"A","sv":"Varning för kaj","en":"","svText":"Märket anger en plats där vägen slutar mot vatten.","enText":"","tip":"","kw":[],"img":"A7-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-kaj/","related":[]},{"id":"A8","cat":"A","sv":"Varning för ojämn väg","en":"","svText":"Märket anger sådana ojämnheter eller skador i vägbanan som medför att det är lämpligt att färdas med lägre hastighet än som annars skulle varit fallet.","enText":"","tip":"","kw":[],"img":"A8-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-ojamn-vag/","related":[]},{"id":"A9","cat":"A","sv":"Varning för farthinder","en":"","svText":"Märkena anger upphöjning eller grop som anlagts som fartdämpande åtgärd.","enText":"","tip":"","kw":[],"img":"A9-1","variants":[{"key":"A9-2","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-farthinder/","related":[]},{"id":"A10","cat":"A","sv":"Varning för slirig väg","en":"","svText":"Märket anger att vägen kan vara slirig. Endast om det finns särskilda skäl används märket för att varna för halka på grund av snö eller is.","enText":"","tip":"","kw":[],"img":"A10-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-slirig-vag/","related":[]},{"id":"A11","cat":"A","sv":"Varning för stenskott","en":"","svText":"Märket anger risk för stenskott. Märket används inte på grusvägar eller liknande vägar där stenskott är vanligt förekommande.","enText":"","tip":"","kw":[],"img":"A11-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-stenskott/","related":[]},{"id":"A12","cat":"A","sv":"Varning för stenras","en":"","svText":"Märket anger risk för stenras och för att stenar kan förekomma på vägen på grund av stenras. Symbolen är anpassad efter förhållandena på platsen.","enText":"","tip":"","kw":[],"img":"A12-1","variants":[{"key":"A12-2","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-stenras/","related":[]},{"id":"A13","cat":"A","sv":"Varning för övergångsställe","en":"","svText":"","enText":"","tip":"","kw":[],"img":"A13-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-overgangsstalle/","related":[]},{"id":"A14","cat":"A","sv":"Varning för gående","en":"","svText":"Märket anger en vägsträcka där gående ofta korsar eller uppehåller sig på eller vid vägen.","enText":"","tip":"","kw":[],"img":"A14","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-gaende/","related":[]},{"id":"A15","cat":"A","sv":"Varning för barn","en":"","svText":"Märket anger en vägsträcka där barn ofta korsar eller uppehåller sig på eller vid vägen.","enText":"","tip":"","kw":[],"img":"A15-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-barn/","related":[]},{"id":"A16","cat":"A","sv":"Varning för cyklande och mopedförare","en":"","svText":"Märket anger en vägsträcka där cyklande eller mopedförare ofta korsar eller kör in på vägen.","enText":"","tip":"","kw":[],"img":"A16-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-cyklande-och-mopedforare/","related":[]},{"id":"A17","cat":"A","sv":"Varning för skidåkare","en":"","svText":"Märket anger en plats där skidåkare ofta korsar eller uppehåller sig på vägen.","enText":"","tip":"","kw":[],"img":"A17-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-skidakare/","related":[]},{"id":"A18","cat":"A","sv":"Varning för ridande","en":"","svText":"Märket anger en vägsträcka där ridande ofta korsar eller uppehåller sig på vägen.","enText":"","tip":"","kw":[],"img":"A18-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-ridande/","related":[]},{"id":"A19","cat":"A","sv":"Varning för djur","en":"","svText":"Märket anger en plats eller vägsträcka där det finns särskild risk för djur på eller vid vägen. Andra symboler kan förekomma på märket. Transportstyrelsen får meddela föreskrifter om vilka andra symboler som får förekomma.","enText":"","tip":"","kw":[],"img":"A19-1","variants":[{"key":"A19-2","en":""},{"key":"A19-3","en":""},{"key":"A19-4","en":""},{"key":"A19-5","en":""},{"key":"A19-6","en":""},{"key":"A19-7","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-djur/","related":[]},{"id":"A20","cat":"A","sv":"Varning för vägarbete","en":"","svText":"Märket anger en vägsträcka där vägarbete eller liknande arbete pågår.","enText":"","tip":"","kw":[],"img":"A20-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-vagarbete/","related":[]},{"id":"A21","cat":"A","sv":"Slut på sträcka med vägarbete","en":"","svText":"Märket anger slut på en vägsträcka med vägarbete som märkts ut med märke A20, varning för vägarbete. Märket är inte uppsatt om det ändå tydligt framgår var sträckan slutar.","enText":"","tip":"","kw":[],"img":"A21-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/slut-pa-stracka-med-vagarbete/","related":[]},{"id":"A22","cat":"A","sv":"Varning för flerfärgssignal","en":"","svText":"Märket anger en plats där trafiken regleras med flerfärgssignal med tre ljusöppningar. Inom tättbebyggt område är märket uppsatt endast om det finns särskilda skäl för det.","enText":"","tip":"","kw":[],"img":"A22-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-flerfargssignal/","related":[]},{"id":"A23","cat":"A","sv":"Varning för lågt flygande flygplan","en":"","svText":"","enText":"","tip":"","kw":[],"img":"A23-1","variants":[{"key":"A23-2","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-lagt-flygande-flygplan/","related":[]},{"id":"A24","cat":"A","sv":"Varning för sidvind","en":"","svText":"Märket anger en vägsträcka där det ofta förekommer stark sidvind. Symbolen är anpassad efter förhållandena på platsen.","enText":"","tip":"","kw":[],"img":"A24-1","variants":[{"key":"A24-2","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-sidvind/","related":[]},{"id":"A25","cat":"A","sv":"Varning för mötande trafik","en":"","svText":"Märket anger att en körbana med enkelriktad trafik övergår i en körbana med trafik i båda riktningarna.","enText":"","tip":"","kw":[],"img":"A25-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-motande-trafik/","related":[]},{"id":"A26","cat":"A","sv":"Varning för tunnel","en":"","svText":"","enText":"","tip":"","kw":[],"img":"A26-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-tunnel/","related":[]},{"id":"A27","cat":"A","sv":"Varning för svag vägkant eller hög körbanekant","en":"","svText":"","enText":"","tip":"","kw":[],"img":"A27-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-svag-vagkant-eller-hog-korbanekant/","related":[]},{"id":"A28","cat":"A","sv":"Varning för vägkorsning","en":"","svText":"Märket anger en vägkorsning där bestämmelserna i 3 kap. 18 § trafikförordningen (1998:1276) är tillämpliga.","enText":"","tip":"","kw":[],"img":"A28-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-vagkorsning/","related":[]},{"id":"A29","cat":"A","sv":"Varning för vägkorsning där trafikanter på anslutande väg har väjningsplikt eller stopplikt","en":"","svText":"Märket anger en vägkorsning där förare av fordon på anslutande vägar har väjningsplikt eller stopplikt. Symbolen är anpassad efter förhållandena på platsen.","enText":"","tip":"","kw":[],"img":"A29-1","variants":[{"key":"A29-2","en":""},{"key":"A29-3","en":""},{"key":"A29-4","en":""},{"key":"A29-5","en":""},{"key":"A29-6","en":""},{"key":"A29-7","en":""},{"key":"A29-8","en":""},{"key":"A29-9","en":""},{"key":"A29-10","en":""},{"key":"A29-11","en":""},{"key":"A29-12","en":""},{"key":"A29-13","en":""},{"key":"A29-14","en":""},{"key":"A29-15","en":""},{"key":"A29-16","en":""},{"key":"A29-17","en":""},{"key":"A29-18","en":""},{"key":"A29-19","en":""},{"key":"A29-20","en":""},{"key":"A29-21","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-vagkorsning-dar-trafikanter-pa-anslutande-vag-har-vajningsplikt-eller-stopplikt/","related":[]},{"id":"A30","cat":"A","sv":"Varning för cirkulationsplats","en":"","svText":"","enText":"","tip":"","kw":[],"img":"A30-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-cirkulationsplats/","related":[]},{"id":"A31","cat":"A","sv":"Varning för långsamtgående fordon","en":"","svText":"Märket anger en plats där långsamtgående fordon ofta korsar eller kör in på vägen.","enText":"","tip":"","kw":[],"img":"A31","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-langsamtgaende-fordon/","related":[]},{"id":"A32","cat":"A","sv":"Varning för fordon med förspänt dragdjur","en":"","svText":"Märket anger en vägsträcka där fordon förspända med dragdjur ofta korsar eller uppehåller sig på vägen. Andra symboler kan förekomma på märket. Transportstyrelsen får meddela föreskrifter om vilka andra symboler som får förekomma.","enText":"","tip":"","kw":[],"img":"A32-1","variants":[{"key":"A32-2","en":""},{"key":"A32-3","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-fordon-med-forspant-dragdjur/","related":[]},{"id":"A33","cat":"A","sv":"Varning för terrängskotertrafik","en":"","svText":"Märket anger en plats där terrängskotrar ofta korsar eller kör in på vägen.","enText":"","tip":"","kw":[],"img":"A33-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-terrangskotertrafik/","related":[]},{"id":"A34","cat":"A","sv":"Varning för kö","en":"","svText":"Märket anger en vägsträcka där det finns risk för köbildning.","enText":"","tip":"","kw":[],"img":"A34-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-ko/","related":[]},{"id":"A35","cat":"A","sv":"Varning för järnvägskorsning med bommar","en":"","svText":"Märket anger en korsning med järnväg eller spårväg där det finns bommar.","enText":"","tip":"","kw":[],"img":"A35-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-jarnvagskorsning-med-bommar/","related":[]},{"id":"A36","cat":"A","sv":"Varning för järnvägskorsning utan bommar","en":"","svText":"","enText":"","tip":"","kw":[],"img":"A36-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-jarnvagskorsning-utan-bommar/","related":[]},{"id":"A37","cat":"A","sv":"Varning för korsning med spårväg utan bommar","en":"","svText":"","enText":"","tip":"","kw":[],"img":"A37-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-korsning-med-sparvag-utan-bommar/","related":[]},{"id":"A38","cat":"A","sv":"Avstånd till plankorsning","en":"","svText":"Märkena anger avståndet till en plankorsning i tredjedelar. Märket med tre markeringar är utom tättbebyggt område, uppsatt under något av märkena A35, varning för järnvägskorsning med bommar, A36, varning för järnvägskorsning utan bommar, eller A37, varning för korsning med spårväg utan bommar. Märket med två markeringar anger två tredjedels avstånd till plankorsning och märket med en markering anger den sista tredjedelen av avståndet.","enText":"","tip":"","kw":[],"img":"A38-1","variants":[{"key":"A38-2","en":""},{"key":"A38-3","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/avstand-till-plankorsning/","related":[]},{"id":"A39","cat":"A","sv":"Kryssmärke","en":"","svText":"Märket anger en korsning med järnväg eller spårväg med ett eller flera spår. Märket är uppsatt omedelbart före en plankorsning. Det behöver inte vara uppsatt vid enskild väg med lite trafik där det kan underlåtas utan fara för trafiksäkerheten. Märket kan även vara uppsatt viden annan korsning med järnväg eller spårväg än en plankorsning.","enText":"","tip":"","kw":[],"img":"A39-1","variants":[{"key":"A39-2","en":""},{"key":"A39-3","en":""},{"key":"A39-4","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/kryssmarke/","related":[]},{"id":"A40","cat":"A","sv":"Varning för annan fara","en":"","svText":"Märket anger en annan fara än sådan som kan anges med något annat varningsmärke. Farans art anges på en tilläggstavla.","enText":"","tip":"","kw":[],"img":"A40-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-annan-fara/","related":[]},{"id":"A41","cat":"A","sv":"Varning för olycka","en":"","svText":"","enText":"","tip":"","kw":[],"img":"A41","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-olycka/","related":[]},{"id":"B1","cat":"B","sv":"Väjningsplikt","en":"","svText":"Märket anger att förare har väjningsplikt mot fordon på korsande väg eller led och att bestämmelserna i 3 kap. 5 § trafikförordningen (1998:1276) är tillämpliga. Märket kan vara uppsatt tillsammans med tilläggstavla T2, avstånd, som förberedande upplysning om väjningsplikt och tillsammans med tilläggstavla T3, avstånd till stopplikt, som förberedande upplysning om stopplikt. Om samtliga tillfarter i en korsning har väjningsplikt anges detta med tilläggstavla T13, flervägsväjning .","enText":"","tip":"","kw":[],"img":"B1-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vajningspliktsmarken/vajningsplikt/","related":[]},{"id":"B2","cat":"B","sv":"Stopplikt","en":"","svText":"Märket anger att förare har stopplikt före infart på korsande väg, led eller spårområde och att bestämmelserna i 3 kap. 19 § trafikförordningen är tillämpliga. Om samtliga tillfarter i en korsning har stopplikt anges detta med tilläggstavla T14, flervägsstopp.","enText":"","tip":"","kw":[],"img":"B2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vajningspliktsmarken/stopplikt/","related":[]},{"id":"B3","cat":"B","sv":"Övergångsställe","en":"","svText":"Märkena, som är likvärdiga och kan användas var för sig eller tillsammans, anger ett övergångsställe. Vid obevakade övergångsställen är för fordonsförare bestämmelserna i 3 kap. 61 § och för gående bestämmelserna i 7 kap. 4 § trafikförordningen tillämpliga.","enText":"","tip":"","kw":[],"img":"B3-1","variants":[{"key":"B3-2","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vajningspliktsmarken/overgangsstalle/","related":[]},{"id":"B4","cat":"B","sv":"Huvudled","en":"","svText":"Märket är uppsatt vid huvudledens början och upprepat efter varje korsning med annan väg än sådan som avses i 3 kap. 21 § andra stycket trafikförordningen, om det inte ändå tydligt framgår att huvudleden fortsätter efter korsningen.","enText":"","tip":"","kw":[],"img":"B4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vajningspliktsmarken/huvudled/","related":[]},{"id":"B5","cat":"B","sv":"Huvudled upphör","en":"","svText":"","enText":"","tip":"","kw":[],"img":"B5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vajningspliktsmarken/huvudled-upphor/","related":[]},{"id":"B6","cat":"B","sv":"Väjningsplikt mot mötande trafik","en":"","svText":"","enText":"","tip":"","kw":[],"img":"B6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vajningspliktsmarken/vajningsplikt-mot-motande-trafik/","related":[]},{"id":"B7","cat":"B","sv":"Mötande trafik har väjningsplikt","en":"","svText":"","enText":"","tip":"","kw":[],"img":"B7-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vajningspliktsmarken/motande-trafik-har-vajningsplikt/","related":[]},{"id":"B8","cat":"B","sv":"Cykelöverfart","en":"","svText":"Märket anger en cykelöverfart. Vid cykelöverfarter är för fordonsförare bestämmelserna i 3 kap. 61 a § och för cyklande och förare av moped klass II bestämmelserna i 6 kap. 6 § trafikförordningen tillämpliga.","enText":"","tip":"","kw":[],"img":"B8-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vajningspliktsmarken/cykeloverfart/","related":[]},{"id":"C1","cat":"C","sv":"Förbud mot infart med fordon","en":"","svText":"","enText":"","tip":"","kw":[],"img":"C1-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-infart-med-fordon/","related":[]},{"id":"C2","cat":"C","sv":"Förbud mot trafik med fordon","en":"","svText":"","enText":"","tip":"","kw":[],"img":"C2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-fordon/","related":[]},{"id":"C3","cat":"C","sv":"Förbud mot trafik med annat motordrivet fordon än moped klass II","en":"","svText":"Avser förbudet även moped klass II anges detta på en tilläggstavla.","enText":"","tip":"","kw":[],"img":"C3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-annat-motordrivet-fordon-an-moped-klass-ii/","related":[]},{"id":"C4","cat":"C","sv":"Förbud mot trafik med motordrivet fordon med fler än två hjul","en":"","svText":"","enText":"","tip":"","kw":[],"img":"C4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-motordrivet-fordon-med-fler-an-tva-hjul/","related":[]},{"id":"C5","cat":"C","sv":"Förbud mot trafik med motorcykel och moped klass I","en":"","svText":"","enText":"","tip":"","kw":[],"img":"C5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-motorcykel-och-moped-klass-i/","related":[]},{"id":"C6","cat":"C","sv":"Förbud mot trafik med motordrivet fordon med tillkopplad släpvagn","en":"","svText":"Märket anger förbud mot trafik med motordrivet fordon med tillkopplad släpvagn av annat slag än påhängsvagn eller släpkärra. Avser förbudet även trafik med motordrivet fordon med tillkopplad påhängsvagn eller släpkärra anges det på en tilläggstavla. Avser förbudet endast fordonståg med släpvagn vars totalvikt överstiger visst tontal anges det på tilläggstavla T5, totalvikt.","enText":"","tip":"","kw":[],"img":"C6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-motordrivet-fordon-med-tillkopplad-slapvagn/","related":[]},{"id":"C7","cat":"C","sv":"Förbud mot trafik med tung lastbil","en":"","svText":"","enText":"","tip":"","kw":[],"img":"C7-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-tung-lastbil/","related":[]},{"id":"C8","cat":"C","sv":"Förbud mot trafik med traktor och motorredskap klass II","en":"","svText":"Avser förbudet även trafik med traktor b eller motorredskap klass I anges det på en tilläggstavla.","enText":"","tip":"","kw":[],"img":"C8-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-traktor-och-motorredskap-klass-ii/","related":[]},{"id":"C9","cat":"C","sv":"Förbud mot trafik med fordon lastat med farligt gods","en":"","svText":"Märket anger förbud mot trafik med fordon med sådan last som omfattas av krav på märkning med orangefärgad skylt enligt föreskrifter som har meddelats med stöd av lagen (2006:263) om transport av farligt gods. Tillsammans med tilläggstavla T23, tunnelkategori, anger märket tunnelkategori.","enText":"","tip":"","kw":[],"img":"C9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-fordon-lastat-med-farligt-gods/","related":[]},{"id":"C10","cat":"C","sv":"Förbud mot trafik med cykel och moped klass II","en":"","svText":"Avser förbudet även trafik med moped klass I anges det på en tilläggstavla.","enText":"","tip":"","kw":[],"img":"C10-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-cykel-och-moped-klass-ii/","related":[]},{"id":"C11","cat":"C","sv":"Förbud mot trafik med moped klass II","en":"","svText":"Avser förbudet även trafik med moped klass I anges det på en tilläggstavla.","enText":"","tip":"","kw":[],"img":"C11-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-moped-klass-ii/","related":[]},{"id":"C12","cat":"C","sv":"Förbud mot trafik med fordon förspänt med dragdjur","en":"","svText":"","enText":"","tip":"","kw":[],"img":"C12-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-fordon-forspant-med-dragdjur/","related":[]},{"id":"C13","cat":"C","sv":"Förbud mot trafik med terrängmotorfordon och terrängsläp","en":"","svText":"Gäller förbudet inte terrängvagn anges det på en tilläggstavla.","enText":"","tip":"","kw":[],"img":"C13-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-terrangmotorfordon-och-terrangslap/","related":[]},{"id":"C14","cat":"C","sv":"Förbud mot ridning","en":"","svText":"Avser förbudet även ledande av riddjur anges det på en tilläggstavla.","enText":"","tip":"","kw":[],"img":"C14-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-ridning/","related":[]},{"id":"C15","cat":"C","sv":"Förbud mot gångtrafik","en":"","svText":"","enText":"","tip":"","kw":[],"img":"C15-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-gangtrafik/","related":[]},{"id":"C16","cat":"C","sv":"Begränsad fordonsbredd","en":"","svText":"Märket anger förbud mot trafik med fordon över en viss bredd. Största tillåtna bredd anges på märket.","enText":"","tip":"","kw":[],"img":"C16-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/begransad-fordonsbredd/","related":[]},{"id":"C17","cat":"C","sv":"Begränsad fordonshöjd","en":"","svText":"Märket anger förbud mot trafik med fordon över en viss höjd om den fria höjden är lägre än 4,5 meter. Högsta tillåtna fordonshöjd anges på märket.","enText":"","tip":"","kw":[],"img":"C17-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/begransad-fordonshojd/","related":[]},{"id":"C18","cat":"C","sv":"Begränsad fordonslängd","en":"","svText":"Märket anger förbud mot trafik med fordon eller fordonståg över en viss längd. Längsta tillåtna längd anges på märket.","enText":"","tip":"","kw":[],"img":"C18-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/begransad-fordonslangd/","related":[]},{"id":"C19","cat":"C","sv":"Minsta avstånd","en":"","svText":"Märket anger förbud mot att hålla kortare avstånd till framförvarande motordrivna fordon i samma färdriktning än som anges på märket. Minsta tillåtna avstånd anges på märket.","enText":"","tip":"","kw":[],"img":"C19-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/minsta-avstand/","related":[]},{"id":"C20","cat":"C","sv":"Begränsad bruttovikt på fordon","en":"","svText":"Högsta tillåtna bruttovikt anges på märket.","enText":"","tip":"","kw":[],"img":"C20-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/begransad-bruttovikt-pa-fordon/","related":[]},{"id":"C21","cat":"C","sv":"Begränsad bruttovikt på fordon och fordonståg","en":"","svText":"Högsta tillåtna bruttovikt anges på märket.","enText":"","tip":"","kw":[],"img":"C21-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/begransad-bruttovikt-pa-fordon-och-fordonstag/","related":[]},{"id":"C22","cat":"C","sv":"Bärighetsklass","en":"","svText":"Vägens bärighetsklass anges på märket.","enText":"","tip":"","kw":[],"img":"C22-3","variants":[{"key":"C22-2","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/barighetsklass/","related":[]},{"id":"C23","cat":"C","sv":"Begränsat axeltryck","en":"","svText":"Högsta tillåtna axeltryck anges på märket.","enText":"","tip":"","kw":[],"img":"C23-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/begransat-axeltryck/","related":[]},{"id":"C24","cat":"C","sv":"Begränsat boggitryck","en":"","svText":"Högsta tillåtna boggitryck anges på märket.","enText":"","tip":"","kw":[],"img":"C24-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/begransat-boggitryck/","related":[]},{"id":"C25","cat":"C","sv":"Förbud mot sväng i korsning","en":"","svText":"Förbudet gäller den korsning eller motsvarande som märket är placerat i eller före. Märket kan avse flera korsningar. Sträckans längd anges då på en tilläggstavla. Symbolen är anpassad efter förhållandena på platsen.","enText":"","tip":"","kw":[],"img":"C25-1","variants":[{"key":"C25-2","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-svang-i-korsning/","related":[]},{"id":"C26","cat":"C","sv":"Förbud mot U-sväng","en":"","svText":"Förbudet gäller den korsning eller motsvarande som märket är placerat i eller före. Märket kan avse flera korsningar. Sträckans längd anges då på en tilläggstavla. Symbolen är anpassad efter förhållandena på platsen.","enText":"","tip":"","kw":[],"img":"C26-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-u-svang/","related":[]},{"id":"C27","cat":"C","sv":"Förbud mot omkörning","en":"","svText":"Märket anger förbud mot att köra om andra motordrivna fordon än tvåhjuliga mopeder och tvåhjuliga motorcyklar utan sidvagn. Förbudet gäller på den väg märket är uppsatt och till den plats där märke C28, slut på förbud mot omkörning, är uppsatt.","enText":"","tip":"","kw":[],"img":"C27-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-omkorning/","related":[]},{"id":"C28","cat":"C","sv":"Slut på förbud mot omkörning","en":"","svText":"","enText":"","tip":"","kw":[],"img":"C28-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/slut-pa-forbud-mot-omkorning/","related":[]},{"id":"C29","cat":"C","sv":"Förbud mot omkörning med tung lastbil","en":"","svText":"Märket anger förbud mot att med en tung lastbil köra om andra motordrivna fordon än tvåhjuliga mopeder och tvåhjuliga motorcyklar utan sidvagn. Förbudet gäller på den väg märket är uppsatt till den plats där märke C30, slut på förbud mot omkörning med tung lastbil, är uppsatt.","enText":"","tip":"","kw":[],"img":"C29-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-omkorning-med-tung-lastbil/","related":[]},{"id":"C30","cat":"C","sv":"Slut på förbud mot omkörning med tung lastbil","en":"","svText":"","enText":"","tip":"","kw":[],"img":"C30-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/slut-pa-forbud-mot-omkorning-med-tung-lastbil/","related":[]},{"id":"C31","cat":"C","sv":"Hastighetsbegränsning","en":"","svText":"Märket anger förbud mot att föra fordon med högre hastighet än den som anges på märket. Angivelsen gäller till den plats där en annan hastighetsbegränsning anges med märket, eller där märke C32, tillfällig hastighetsbegränsning upphör, E7, gågata, eller E9, gångfartsområde, satts upp. Märket behöver inte vara upprepat efter en vägkorsning om samma högsta tillåtna hastighet gäller på den korsande vägen.","enText":"","tip":"","kw":[],"img":"C31-3","variants":[{"key":"C31-4","en":""},{"key":"C31-5","en":""},{"key":"C31-6","en":""},{"key":"C31-7","en":""},{"key":"C31-8","en":""},{"key":"C31-9","en":""},{"key":"C31-10","en":""},{"key":"C31-11","en":""},{"key":"C31-12","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/hastighetsbegransning/","related":[]},{"id":"C32","cat":"C","sv":"Tillfällig hastighetsbegränsning upphör","en":"","svText":"Märket anger att en tillfällig hastighet som märkts ut med märke C31, hastighetsbegränsning, upphör.","enText":"","tip":"","kw":[],"img":"C32-3","variants":[{"key":"C32-2","en":""},{"key":"C32-4","en":""},{"key":"C32-5","en":""},{"key":"C32-6","en":""},{"key":"C32-7","en":""},{"key":"C32-8","en":""},{"key":"C32-9","en":""},{"key":"C32-10","en":""},{"key":"C32-11","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/tillfallig-hastighetsbegransning-upphor/","related":[]},{"id":"C33","cat":"C","sv":"Stopp vid tull","en":"","svText":"","enText":"","tip":"","kw":[],"img":"C33-1","variants":[{"key":"C33-2","en":""},{"key":"C33-3","en":""},{"key":"C33-4","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/stopp-vid-tull/","related":[]},{"id":"C34","cat":"C","sv":"Stopp för angivet ändamål","en":"","svText":"Märket anger skyldighet att stanna av den anledning som anges under det vågräta strecket. Om märket är uppsatt före en trafiksignal, anger det att fordon som ska passera signalen ska stanna vid röd signalbild. Fordonet ska stannas vid en stopplinje eller, om sådan saknas, vid märket. Transportstyrelsen får meddela föreskrifter om vilka andra anledningar som får anges.","enText":"","tip":"","kw":[],"img":"C34","variants":[{"key":"C34-3","en":""},{"key":"C34-4","en":""},{"key":"C34-5","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/stopp-for-angivet-andamal/","related":[]},{"id":"C35","cat":"C","sv":"Förbud mot att parkera fordon","en":"","svText":"Märket anger förbud mot att parkera fordon. Angivelsen gäller på den sida av vägen där märket är uppsatt. Angivelsen börjar gälla där märket satts upp och gäller enligt vad som anges på en tilläggstavla, till den plats där någon annan bestämmelse om stannande eller parkering märkts ut, till nästa korsning med en annan väg än sådan som avses i 3 kap. 21 § andra stycket trafikförordningen (1998:1276) eller till den plats dessförinnan där ett motsvarande märke med tilläggstavla T11, utsträckning, med nedåtriktad pil, har satts upp. Om en annan bestämmelse gäller på en kortare sträcka gäller angivelsen på nytt efter sträckans slut utan att det upprepas. Angivelsen gäller också på nytt utan att märket satts upp igen i det fall en parkeringsplats anordnats vid sidan av körbanan. Märket anger inte rätt att stanna där fordon inte får stannas eller parkeras enligt trafikförordningen, om inte detta tydligt framgår av märkets placering eller anges på en tilläggstavla.","enText":"","tip":"","kw":[],"img":"C35-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-att-parkera-fordon/","related":[]},{"id":"C36","cat":"C","sv":"Förbud mot att parkera fordon på dag med udda datum","en":"","svText":"De närmare föreskrifterna till märke C35, förbud mot att parkera fordon, gäller även till detta märke.","enText":"","tip":"","kw":[],"img":"C36-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-att-parkera-fordon-pa-dag-med-udda-datum/","related":[]},{"id":"C37","cat":"C","sv":"Förbud mot att parkera fordon på dag med jämnt datum","en":"","svText":"De närmare föreskrifterna till märke C35, förbud mot att parkera fordon, gäller även till detta märke.","enText":"","tip":"","kw":[],"img":"C37-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-att-parkera-fordon-pa-dag-med-jamnt-datum/","related":[]},{"id":"C38","cat":"C","sv":"Datumparkering","en":"","svText":"Märket anger förbud mot att parkera fordon på dagar med jämnt datum på den sida av vägen som har jämna adressnummer och på dagar med udda datum på den sida av vägen som har udda adressnummer. De närmare föreskrifterna till märke C35, förbud mot att parkera fordon, gäller även till detta märke.","enText":"","tip":"","kw":[],"img":"C38-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/datumparkering/","related":[]},{"id":"C39","cat":"C","sv":"Förbud mot att stanna och parkera fordon","en":"","svText":"Märket anger förbud mot att stanna och parkera fordon. De närmare föreskrifterna till märke C35, förbud mot att parkera fordon, andra stycket gäller även till detta märke.","enText":"","tip":"","kw":[],"img":"C39-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-att-stanna-och-parkera-fordon/","related":[]},{"id":"C40","cat":"C","sv":"Ändamålsplats","en":"","svText":"Har ändamålet angetts med lastplats är ändamålet lastning eller lossning av tungt eller skrymmande gods. Transportstyrelsen får meddela föreskrifter om vilka andra ändamål som får anges och hur de anges.","enText":"","tip":"","kw":[],"img":"C40-1","variants":[{"key":"C40-2","en":""},{"key":"C40-3","en":""},{"key":"C40-4","en":""},{"key":"C40-5","en":""},{"key":"C40-6","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/andamalsplats/","related":[]},{"id":"C41","cat":"C","sv":"Slut på ändamålsplats","en":"","svText":"Märket behöver inte vara uppsatt om det ändå tydligt framgår att ändamålsplatsen upphör. Märket är anpassat till märke C40, ändamålsplats.","enText":"","tip":"","kw":[],"img":"C41-1","variants":[{"key":"C41-2","en":""},{"key":"C41-3","en":""},{"key":"C41-4","en":""},{"key":"C41-5","en":""},{"key":"C41-6","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/slut-pa-andamalsplats/","related":[]},{"id":"C42","cat":"C","sv":"Vändplats","en":"","svText":"Märket anger en plats som är avsedd för vändning av fordon och att det är förbjudet att parkera fordon. Om i stället märke C39, förbud mot att stanna och parkera fordon, är infogat i märket anger det att det är förbjudet att stanna eller parkera fordon.","enText":"","tip":"","kw":[],"img":"C42-1","variants":[{"key":"C42-2","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/vandplats/","related":[]},{"id":"C43","cat":"C","sv":"Slut på vändplats","en":"","svText":"Märket behöver inte vara uppsatt om det ändå tydligt framgår att vändplatsen upphör. Märket är anpassat till märke C42, vändplats.","enText":"","tip":"","kw":[],"img":"C43-1","variants":[{"key":"C43-2","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/slut-pa-vandplats/","related":[]},{"id":"C44","cat":"C","sv":"Förbud mot trafik med annat motordrivet fordon med dubbdäck än moped klass II","en":"","svText":"Avser förbudet även moped klass II anges det på en tilläggstavla.","enText":"","tip":"","kw":[],"img":"C44","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-annat-motordrivet-fordon-med-dubbdack-an-moped-klass-ii/","related":[]},{"id":"C45","cat":"C","sv":"Särskilda bestämmelser för stannande och parkering","en":"","svText":"Märket anger det förbud som anges med det infogade märket. Märket kan också ange avvikelse från den reglering som anges med det märke som den är uppsatt under. Andra förbud kan anges med märket. Transportstyrelsen får meddela föreskrifter om vilka andra förbudsmärken som får infogas. Märket är uppsatt under något av märkena C35, förbud mot att parkera fordon, C36, förbud mot att parkera fordon på dag med udda datum, C37, förbud mot att parkera fordon på dag med jämnt datum, C38, datumparkering, C39, förbud mot att stanna och parkera fordon, C40, ändamålsplats, C42, vändplats, D10, påbjudet körfält eller körbana för fordon i linjetrafik m.fl., E19, parkering eller E20, områdesmärke. Märke E20, områdesmärke, får vara infogat. Är märket infogat gäller de närmare föreskrifterna till märke E20, områdesmärke. För tid gäller de närmare föreskrifterna för tilläggstavla T6, tidsangivelse. Andra begränsningar kan endast vara angivna på märket.","enText":"","tip":"","kw":[],"img":"C45","variants":[{"key":"C45-2","en":""},{"key":"C45-3","en":""},{"key":"C45-4","en":""},{"key":"C45-5","en":""},{"key":"C45-6","en":""},{"key":"C45-7","en":""},{"key":"C45-8","en":""},{"key":"C45-9","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/sarskilda-bestammelser-for-stannande-och-parkering/","related":[]},{"id":"C46","cat":"C","sv":"Begränsat trippelaxeltryck","en":"","svText":"Högsta tillåtna trippelaxeltryck anges på märket.","enText":"","tip":"","kw":[],"img":"C46","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/begransat-trippelaxeltryck/","related":[]},{"id":"D1","cat":"D","sv":"Påbjuden körriktning","en":"","svText":"Märket anger att fordon endast får föras i pilens eller, där två pilar finns, i endera pilens riktning. Symbolen är anpassad efter förhållandena på platsen.","enText":"","tip":"","kw":[],"img":"D1-1","variants":[{"key":"D1-2","en":""},{"key":"D1-3","en":""},{"key":"D1-4","en":""},{"key":"D1-5","en":""},{"key":"D1-6","en":""},{"key":"D1-7","en":""},{"key":"D1-8","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/pabjuden-korriktning/","related":[]},{"id":"D2","cat":"D","sv":"Påbjuden körbana","en":"","svText":"Märkena anger att fordon endast får föras förbi märket där pilen visar eller, där två pilar finns, där pilarna visar. Symbolen är anpassad efter förhållandena på platsen.","enText":"","tip":"","kw":[],"img":"D2-1","variants":[{"key":"D2-2","en":""},{"key":"D2-3","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/pabjuden-korbana/","related":[]},{"id":"D3","cat":"D","sv":"Cirkulationsplats","en":"","svText":"","enText":"","tip":"","kw":[],"img":"D3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/cirkulationsplats/","related":[]},{"id":"D4","cat":"D","sv":"Påbjuden cykelbana","en":"","svText":"Om moped klass II inte får föras på banan anges det på en tilläggstavla.","enText":"","tip":"","kw":[],"img":"D4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/pabjuden-cykelbana/","related":[]},{"id":"D5","cat":"D","sv":"Påbjuden gångbana","en":"","svText":"Märket anger bana avsedd endast för gående.","enText":"","tip":"","kw":[],"img":"D5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/pabjuden-gangbana/","related":[]},{"id":"D6","cat":"D","sv":"Påbjuden gång- och cykelbana","en":"","svText":"Märket anger gemensam bana för gående och cyklande. Om moped klass II inte får föras på banan anges det på en tilläggstavla.","enText":"","tip":"","kw":[],"img":"D6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/pabjuden-gang--och-cykelbana/","related":[]},{"id":"D7","cat":"D","sv":"Påbjudna gång- och cykelbanor","en":"","svText":"Märket anger banor som är delade genom vägmarkering, skiljeremsa eller liknande i en del för gående och en del för cyklande. Symbolernas placering på märket anger vilken del av banan som är avsedd för gående respektive cyklande. Om moped klass II inte får föras på banan anges det på en tilläggstavla.","enText":"","tip":"","kw":[],"img":"D7-1","variants":[{"key":"D7-2","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/pabjudna-gang--och-cykelbanor/","related":[]},{"id":"D8","cat":"D","sv":"Påbjuden ridväg","en":"","svText":"Märket anger även att gångtrafik är tillåten.","enText":"","tip":"","kw":[],"img":"D8-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/pabjuden-ridvag/","related":[]},{"id":"D9","cat":"D","sv":"Påbjuden led för terrängmotorfordon och terrängsläp","en":"","svText":"Märket anger även att gångtrafik är tillåten.","enText":"","tip":"","kw":[],"img":"D9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/pabjuden-led-for-terrangmotorfordon-och-terrangslap/","related":[]},{"id":"D10","cat":"D","sv":"Påbjudet körfält eller körbana för fordon i linjetrafik med flera","en":"","svText":"Märket anger även att fordon som anges i 8 kap. 2 § trafikförordningen (1998:1276) får använda körfältet eller körbanan, om inte annat anges på en tilläggstavla. Om andra fordon tillåts trafikera körfältet eller körbanan anges det på en tilläggstavla.","enText":"","tip":"","kw":[],"img":"D10-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/pabjudet-korfalt-eller-korbana-for-fordon-i-linjetrafik-mfl/","related":[]},{"id":"D11","cat":"D","sv":"Slut på påbjuden bana, körfält, väg eller led","en":"","svText":"Märket anger att påbjuden bana, körfält, väg eller led som märkts ut med något av märkena D4-D10 upphör. Märket behöver inte sättas upp om det ändå tydligt framgår att påbudet upphör. Andra symboler för trafikantgrupper eller fordonsslag kan vara infogade i märket. Den symbol som är infogad i märket är samma som på det märke som använts för att märka ut banan, körfältet, vägen eller leden.","enText":"","tip":"","kw":[],"img":"D11-1","variants":[{"key":"D11-2","en":""},{"key":"D11-3","en":""},{"key":"D11-4","en":""},{"key":"D11-5","en":""},{"key":"D11-6","en":""},{"key":"D11-7","en":""},{"key":"D11-8","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/slut-pa-pabjuden-bana-korfalt-vag-eller-led/","related":[]},{"id":"D12","cat":"D","sv":"Påbjuden körriktning för fordon lastat med farligt gods","en":"","svText":"Märket anger påbjuden körriktning för trafik med fordon med sådan last som omfattas av krav på märkning med orangefärgad skylt enligt föreskrifter som har meddelats med stöd av lagen (2006:263) om transport av farligt gods. Bokstaven på märket anger att påbudet endast avser sådana fordon som inte får framföras i en vägtunnel som tillhör den tunnelkategori som motsvarar bokstaven.","enText":"","tip":"","kw":[],"img":"D12-1","variants":[{"key":"D12-2","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/pabjuden-korriktning-for-fordon-lastat-med-farligt-gods/","related":[]},{"id":"E1","cat":"E","sv":"Motorväg","en":"","svText":"Används märket som förberedande upplysning om att en motorväg börjar anges avståndet på en tilläggstavla. Märket kan även vara infogat i ett lokaliseringsmärke.","enText":"","tip":"","kw":[],"img":"E-11","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/motorvag/","related":[]},{"id":"E2","cat":"E","sv":"Motorväg upphör","en":"","svText":"Används märket som förberedande upplysning om att en motorväg upphör anges avståndet på en tilläggstavla. Märket används inte när en motorväg övergår i motortrafikled.","enText":"","tip":"","kw":[],"img":"E2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/motorvag-upphor/","related":[]},{"id":"E3","cat":"E","sv":"Motortrafikled","en":"","svText":"Används märket som förberedande upplysning om att en motortrafikled börjar anges avståndet på en tilläggstavla. Märket kan även vara infogat i ett lokaliseringsmärke.","enText":"","tip":"","kw":[],"img":"E3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/motortrafikled/","related":[]},{"id":"E4","cat":"E","sv":"Motortrafikled upphör","en":"","svText":"Används märket som förberedande upplysning om att en motortrafikled upphör anges avståndet på en tilläggstavla. Märket används inte när en motortrafikled övergår i motorväg.","enText":"","tip":"","kw":[],"img":"E4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/motortrafikled-upphor/","related":[]},{"id":"E5","cat":"E","sv":"Tättbebyggt område","en":"","svText":"Ortnamnet kan vara infogat i märket.","enText":"","tip":"","kw":[],"img":"E5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/tattbebyggt-omrade/","related":[]},{"id":"E6","cat":"E","sv":"Tättbebyggt område upphör","en":"","svText":"Ortnamnet kan vara infogat i märket.","enText":"","tip":"","kw":[],"img":"E6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/tattbebyggt-omrade-upphor/","related":[]},{"id":"E7","cat":"E","sv":"Gågata","en":"","svText":"Märket anger att bestämmelserna i 8 kap. 1 § trafikförordningen (1998:1276) är tillämpliga. Förbud mot att föra fordon som får föras på gågata enligt 8 kap. 1 § andra stycket trafikförordningen anges på en tilläggstavla.","enText":"","tip":"","kw":[],"img":"E7-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/gagata/","related":[]},{"id":"E8","cat":"E","sv":"Gågata upphör","en":"","svText":"Märket behöver inte vara uppsatt om det ändå tydligt framgår att gågatan upphör.","enText":"","tip":"","kw":[],"img":"E8-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/gagata-upphor/","related":[]},{"id":"E9","cat":"E","sv":"Gångfartsområde","en":"","svText":"Märket anger att bestämmelserna i 8 kap. 1 § första stycket trafikförordningen är tillämpliga.","enText":"","tip":"","kw":[],"img":"E9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/gangfartsomrade/","related":[]},{"id":"E10","cat":"E","sv":"Gångfartsområde upphör","en":"","svText":"Märket behöver inte vara uppsatt om det ändå tydligt framgår att gångfartsområdet upphör.","enText":"","tip":"","kw":[],"img":"E10-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/gangfartsomrade-upphor/","related":[]},{"id":"E11","cat":"E","sv":"Rekommenderad lägre hastighet","en":"","svText":"Märket anger en vägsträcka eller ett område där särskilda åtgärder vidtagits eller där förhållandena är sådana att det är lämpligt att färdas med lägre hastighet än den högsta tillåtna. Den rekommenderade lägre hastigheten anges på märket.","enText":"","tip":"","kw":[],"img":"E11-1","variants":[{"key":"E11-2","en":""},{"key":"E11-3","en":""},{"key":"E11-4","en":""},{"key":"E11-5","en":""},{"key":"E11-6","en":""},{"key":"E11-7","en":""},{"key":"E11-8","en":""},{"key":"E11-9","en":""},{"key":"E11-10","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/rekommenderad-lagre-hastighet/","related":[]},{"id":"E12","cat":"E","sv":"Rekommenderad lägre hastighet upphör","en":"","svText":"Märket behöver inte vara uppsatt om det ändå tydligt framgår att sträckan upphör.","enText":"","tip":"","kw":[],"img":"E12-1","variants":[{"key":"E12-2","en":""},{"key":"E12-3","en":""},{"key":"E12-4","en":""},{"key":"E12-5","en":""},{"key":"E12-6","en":""},{"key":"E12-7","en":""},{"key":"E12-8","en":""},{"key":"E12-9","en":""},{"key":"E12-10","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/rekommenderad-lagre-hastighet-upphor/","related":[]},{"id":"E13","cat":"E","sv":"Rekommenderad högsta hastighet","en":"","svText":"Märket används endast som omställbart vägmärke och anger att förhållandena tillfälligt är sådana att det inte är lämpligt att färdas med högre hastighet än den som anges på märket. Den angivna hastigheten är alltid lägre än den högsta tillåtna.","enText":"","tip":"","kw":[],"img":"E13-1","variants":[{"key":"E13-2","en":""},{"key":"E13-3","en":""},{"key":"E13-4","en":""},{"key":"E13-5","en":""},{"key":"E13-6","en":""},{"key":"E13-7","en":""},{"key":"E13-8","en":""},{"key":"E13-9","en":""},{"key":"E13-10","en":""},{"key":"E13-11","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/rekommenderad-hogsta-hastighet/","related":[]},{"id":"E14","cat":"E","sv":"Rekommenderad högsta hastighet upphör","en":"","svText":"Märket behöver inte vara uppsatt om det ändå tydligt framgår att de tillfälliga förhållandena upphört.","enText":"","tip":"","kw":[],"img":"E14-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/rekommenderad-hogsta-hastighet-upphor/","related":[]},{"id":"E15","cat":"E","sv":"Sammanvävning","en":"","svText":"Märket upplyser om att två körfält eller körbanor löper samman och att förarna ska anpassa sig till de nya förhållandena på platsen enligt bestämmelserna i 3 kap. 44 § trafikförordningen. Märket används även som förberedande upplysning om att två körfält eller körbanor löper samman. Avståndet anges då på en tilläggstavla.","enText":"","tip":"","kw":[],"img":"E15-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/sammanvavning/","related":[]},{"id":"E16","cat":"E","sv":"Enkelriktad trafik","en":"","svText":"Märket anger att fordonstrafiken på vägen är enkelriktad i pilens riktning. Uppåtriktad pil anger att trafiken är enkelriktad i riktning rakt fram.","enText":"","tip":"","kw":[],"img":"E16-1","variants":[{"key":"E16-2","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/enkelriktad-trafik/","related":[]},{"id":"E17","cat":"E","sv":"Återvändsväg E17","en":"","svText":"Märket anger att genomfart inte är möjlig. Symbolen anpassas efter förhållandena på platsen och kan vara infogad i ett lokaliseringsmärke. Om genomfart med cykel och moped klass II är möjlig anges det genom att symbol S8, cykel och moped klass II, är infogad i märket.","enText":"","tip":"","kw":[],"img":"E17-1","variants":[{"key":"E17-2","en":""},{"key":"E17-3","en":""},{"key":"E17-4","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/atervandsvag/","related":[]},{"id":"E18","cat":"E","sv":"Mötesplats","en":"","svText":"","enText":"","tip":"","kw":[],"img":"E18-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/motesplats/","related":[]},{"id":"E19","cat":"E","sv":"Parkering","en":"","svText":"Märket anger att parkering är tillåten på en parkeringsplats eller på en sträcka på den sida av vägen där vägmärket är uppsatt. Är märket uppsatt vid en väg anger det att tillåtelsen börjar där märket har satts upp och gäller enligt vad som anges på en tilläggstavla, till den plats där en annan bestämmelse om stannande eller parkering märkts ut eller i annat fall till nästa korsning med en annan väg än sådan som avses i 3 kap. 21 § andra stycket trafikförordningen. Gäller sådan annan bestämmelse på en kortare sträcka gäller dock anvisningen på nytt efter sträckans slut utan att märket upprepas. Används märket vid en särskilt anordnad parkeringsplats gäller anvisningen hela parkeringsplatsen. Märket anger inte rätt att parkera där fordon enligt trafikförordningen inte får stannas eller parkeras, om inte en sådan rätt tydligt framgår av märkets placering eller anges på en tilläggstavla. Märket anger inte heller rätt att parkera fordon i strid mot 3 kap. 49 a § första stycket trafikförordningen. Används märket av en markägare enligt lagen (1984:318) om kontrollavgift vid olovlig parkering anger märket att parkering är tillåten, dock högst 24 timmar i följd vardagar utom vardag före sön- och helgdag, om inte annat framgår av en tilläggstavla. Märket kan vara infogat i ett lokaliseringsmärke. Om märket används som förberedande upplysning, kan uppgift om parkeringsplatsens namn, om att parkeringsplatsen är fullbelagd eller att det finns lediga platser lämnas i anslutning till märket.","enText":"","tip":"","kw":[],"img":"E19-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/parkering/","related":[]},{"id":"E20","cat":"E","sv":"Områdesmärke","en":"","svText":"Märket anger att ett område börjar med de förbud eller tillåtelser som anges med det infogade märket. Avvikelser från anvisningarna på märket kan anges genom tilläggstavlor. Tidsbegränsningar kan även infogas i märket. Märket är uppsatt vid infarterna till området och gäller till den plats där tavla E21, slut på område, är uppsatt eller det på annat tydligt sätt framgår att anvisningarna på märket inte gäller. Inom området kan det förekomma avvikelser från anvisningarna på märket. Dessa avvikelser anges genom andra vägmärken och tilläggstavlor. Anvisningarna på märket gäller även efter sådan avvikelse utan att märket upprepas. Andra förbud eller tillåtelser kan anges på märket. Transportstyrelsen får meddela föreskrifter om vilka andra vägmärken som får infogas.","enText":"","tip":"","kw":[],"img":"E20-1","variants":[{"key":"E20-2","en":""},{"key":"E20-3","en":""},{"key":"E20-4","en":""},{"key":"E20-5","en":""},{"key":"E20-7","en":""},{"key":"E20-8","en":""},{"key":"E20-9","en":""},{"key":"E20-10","en":""},{"key":"E20-11","en":""},{"key":"E20-12","en":""},{"key":"E20-13","en":""},{"key":"E20-14","en":""},{"key":"E20-15","en":""},{"key":"E20-16","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/omradesmarke/","related":[]},{"id":"E21","cat":"E","sv":"Slut på område","en":"","svText":"Märket anger att ett område med förbud eller tillåtelser som angetts med ett märke E20, områdesmärke, upphör. Utseendet är anpassat till det märke som infogats i märke E20, områdesmärke.","enText":"","tip":"","kw":[],"img":"E21-1","variants":[{"key":"E21-2","en":""},{"key":"E21-3","en":""},{"key":"E21-4","en":""},{"key":"E21-5","en":""},{"key":"E21-6","en":""},{"key":"E21-7","en":""},{"key":"E21-8","en":""},{"key":"E21-9","en":""},{"key":"E21-10","en":""},{"key":"E21-11","en":""},{"key":"E21-12","en":""},{"key":"E21-13","en":""},{"key":"E21-14","en":""},{"key":"E21-15","en":""},{"key":"E21-16","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/slut-pa-omrade2/","related":[]},{"id":"E22","cat":"E","sv":"Busshållplats","en":"","svText":"Märket anger en hållplats för fordon i linjetrafik och skolskjuts om inte hållplatsen tydligt framgår på annat sätt. Trots bestämmelserna i 1 kap. 5 § kan uppgifter om busslinjer, bussföretag och motsvarande förekomma på eller vid märket. Klockslag kan anges på märket.","enText":"","tip":"","kw":[],"img":"E22-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/busshallplats/","related":[]},{"id":"E23","cat":"E","sv":"Taxi","en":"","svText":"Märket anger den, i färdriktningen, bortre gränsen för en särskild uppställningsplats för fordon som används i taxitrafik.","enText":"","tip":"","kw":[],"img":"E23-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/taxi2/","related":[]},{"id":"E24","cat":"E","sv":"Automatisk trafikövervakning","en":"","svText":"Märket anger att automatisk övervakning med kamera eller motsvarande kan ske på en plats eller vägsträcka för övervakning av trafikregler, beskattning eller avgiftsbeläggning. Märket anger vidare att personuppgifter kan registreras enligt Dataskyddsförordningen, lagen (2001:558) om vägtrafikregister eller någon annan registerlag. Gäller anvisningen en längre vägsträcka, anges sträckans längd på tilläggstavla T1, vägsträckas längd. Märket upprepas på lämpliga avstånd.","enText":"","tip":"","kw":[],"img":"E24-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/automatisk-trafikovervakning/","related":[]},{"id":"E25","cat":"E","sv":"Betalväg","en":"","svText":"Märket anger att avgift eller särskild skatt ska betalas vid färd på en viss väg eller inom ett visst område.","enText":"","tip":"","kw":[],"img":"E25-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/betalvag/","related":[]},{"id":"E26","cat":"E","sv":"Tunnel","en":"","svText":"Märket anger tunnel. Tunnelns längd anges och tunnelns namn kan anges på märket. Märket är upprepat efter varje kilometer och kvarvarande tunnellängd anges då på märket.","enText":"","tip":"","kw":[],"img":"E26-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/tunnel/","related":[]},{"id":"E27","cat":"E","sv":"Nöduppställningsplats","en":"","svText":"Märket anger plats för uppställning av fordon vid haveri, motorstopp eller liknande. Symbol för hjälptelefon eller brandsläckare kan vara infogad i märket. Märket är utformat efter förhållandena på platsen. Används märket som förberedande upplysning om nöduppställningsplats anges avståndet på en tilläggstavla.","enText":"","tip":"","kw":[],"img":"E27-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/noduppstallningsplats/","related":[]},{"id":"E28","cat":"E","sv":"Nödutgång","en":"","svText":"Märket anger nödutgång för gående.","enText":"","tip":"","kw":[],"img":"E28-1","variants":[{"key":"E28-2","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/nodutgang/","related":[]},{"id":"E29","cat":"E","sv":"Utrymningsväg","en":"","svText":"Märket anger riktning och avstånd till nödutgång eller motsvarande för gående. Märket är uppsatt med högst 25 meters mellanrum.","enText":"","tip":"","kw":[],"img":"E29-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/utrymningsvag/","related":[]},{"id":"E30","cat":"E","sv":"Särskilda bestämmelser för parkering","en":"","svText":"Märket anger att parkering är tillåten med de infogade villkoren. Märket kan också ange avvikelse från den reglering som anges med det märke som den är uppsatt under. De närmare föreskrifterna för märke E19, parkering, utom sjätte och sjunde styckena, gäller även för detta märke. För tid gäller de närmare föreskrifterna för tilläggstavla T6, tidsangivelse. Andra villkor kan anges på märket. Märket används under något av märkena C35, förbud mot att parkera fordon, C36, förbud mot att parkera fordon på dag med udda datum, C37, förbud mot att parkera fordon på dag med jämnt datum, C38, datumparkering, C39, förbud mot att stanna och parkera fordon, C40, ändamålsplats, C42, vändplats, D10, påbjudet körfält eller körbana för fordon i linjetrafik m.fl., E19, parkering, eller E22, busshållplats.","enText":"","tip":"","kw":[],"img":"E30","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/sarskilda-bestammelser-for-parkering/","related":[]},{"id":"E31","cat":"E","sv":"Miljözon","en":"","svText":"Märket anger att bestämmelserna i 4 kap. 22-24 a §§ trafikförordningen (1998:1276) är tillämpliga. Om märket används som förberedande upplysning om att en miljözon börjar, anges avståndet på en tilläggstavla. Märket kan även vara infogat i ett lokaliseringsmärke. Märket är uppsatt vid infarterna till miljözonen och gäller till den plats där ett märke E6, tättbebyggt område upphör, märke E32, slut på miljözon eller ett annat miljözonsmärke är uppsatt.","enText":"","tip":"","kw":[],"img":"E31-1","variants":[{"key":"E31-2","en":""},{"key":"E31-3","en":""},{"key":"E31-4","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/miljozon/","related":[]},{"id":"E32","cat":"E","sv":"Slut på miljözon","en":"","svText":"Märket anger att en miljözon slutar.","enText":"","tip":"","kw":[],"img":"E32-1","variants":[{"key":"E32-2","en":""},{"key":"E32-3","en":""},{"key":"E32-4","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/slut-pa-miljozon/","related":[]},{"id":"E33","cat":"E","sv":"Cykelgata","en":"","svText":"Märket anger att bestämmelserna i 8 kap. 1 a § trafikförordningen (1998:1276) är tillämpliga.","enText":"","tip":"","kw":[],"img":"E33-CYKELGATA","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/cykelgata/","related":[]},{"id":"E34","cat":"E","sv":"Cykelgata upphör","en":"","svText":"Märket anger att en cykelgata upphör. <b>Kommentar:</b> Det förekommer för närvarande inga närmare föreskrifter om vägmärkets storlekar. Andra vägmärken som E7 Gågata och E11 Rekommenderad lägre hastighet som kan förekomma i likande trafikmiljöer har storlekarna Liten 0,4 x 0,4 m, Normal 0,6 x 0,6 m och Stor 0,8 x 0,8 m.","enText":"","tip":"","kw":[],"img":"E34-CYKELGATA-UPPHOR","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/cykelgata-upphor/","related":[]},{"id":"F1","cat":"F","sv":"Orienteringstavla","en":"","svText":"Märket är en förberedande upplysning om korsning, cirkulationsplats eller motsvarande. Om det finns särskilda skäl kan upplysning om två korsningar anges på märket.","enText":"","tip":"","kw":[],"img":"F1-1","variants":[{"key":"F1-2","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/orienteringstavla2/","related":[]},{"id":"F2","cat":"F","sv":"Orienteringstavla vid förbjuden sväng i korsning","en":"","svText":"Märket är en förberedande upplysning om att det är förbjudet att svänga i en korsning, men att en annan körriktning kan väljas.","enText":"","tip":"","kw":[],"img":"F2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/orienteringstavla-vid-forbjuden-svang-i-korsning/","related":[]},{"id":"F3","cat":"F","sv":"Tabellorienteringstavla","en":"","svText":"Märket är en förberedande upplysning om korsning, cirkulationsplats eller motsvarande. Avståndsangivelsen på märket är anpassad till förhållandena på platsen. Samtliga färdriktningar i korsningen anges.","enText":"","tip":"","kw":[],"img":"F3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/tabellorienteringstavla/","related":[]},{"id":"F4","cat":"F","sv":"Avfartsorienteringstavla","en":"","svText":"Märket är en förberedande upplysning om avfart. Avståndsangivelsen på märket är anpassad till förhållandena på platsen.","enText":"","tip":"","kw":[],"img":"F4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/avfartsorienteringstavla/","related":[]},{"id":"F5","cat":"F","sv":"Vägvisare","en":"","svText":"Märket är uppsatt i anslutning till en korsning. Om avstånd anges ska det anges i hela kilometer.","enText":"","tip":"","kw":[],"img":"F5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/vagvisare/","related":[]},{"id":"F6","cat":"F","sv":"Tabellvägvisare","en":"","svText":"Märket kan användas i stället för märke F5, vägvisare, och är uppsatt på kort avstånd före en korsning, cirkulationsplats eller i utfarten från en cirkulationsplats. Används märket i anslutning till ett sjukhusområde, industriområde eller motsvarande får området anges överst på märket utan riktningsangivelse.","enText":"","tip":"","kw":[],"img":"F6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/tabellvagvisare/","related":[]},{"id":"F7","cat":"F","sv":"Avfartsvisare","en":"","svText":"Märket är uppsatt där avfarten börjar.","enText":"","tip":"","kw":[],"img":"F7-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/avfartsvisare/","related":[]},{"id":"F8","cat":"F","sv":"Körfältsvägvisare","en":"","svText":"Märket anger det eller de körfält som är lämpligt att använda för färd till målet. Märket är uppsatt över det eller de körfält det avser. Körfältsvägvisare kan även användas som förberedande upplysning om avfart. I sådana fall anges avståndet till avfarten under angivelsen för avfarten.","enText":"","tip":"","kw":[],"img":"F8-1","variants":[{"key":"F8-2","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/korfaltsvagvisare/","related":[]},{"id":"F9","cat":"F","sv":"Samlingsmärke för vägvisning","en":"","svText":"Inom klammer anges mål som nås via ett gemensamt vägval och under klammerns spets anges det gemensamma vägvalet. Avståndet till aktuell avfart eller korsning kan anges på en tilläggstavla.","enText":"","tip":"","kw":[],"img":"F9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/samlingsmarke-for-vagvisning/","related":[]},{"id":"F10","cat":"F","sv":"Platsmärke","en":"","svText":"Märket anger en ort eller annan plats av betydelse för orienteringen. Kommun-, stads- eller länsvapen kan vara infogat i märket.","enText":"","tip":"","kw":[],"img":"F10-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/platsmarke/","related":[]},{"id":"F11","cat":"F","sv":"Vägnamn","en":"","svText":"Märket anger namn på en viss väg eller led. Avvikelse från färg får inte ske.","enText":"","tip":"","kw":[],"img":"F11-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/vagnamn/","related":[]},{"id":"F12","cat":"F","sv":"Vattendrag","en":"","svText":"","enText":"","tip":"","kw":[],"img":"F12-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/vattendrag/","related":[]},{"id":"F13","cat":"F","sv":"Avståndstavla","en":"","svText":"Avstånd anges i hela kilometer. Vägnamn eller vägnummer kan vara infogade i märket.","enText":"","tip":"","kw":[],"img":"F13-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/avstandstavla/","related":[]},{"id":"F14","cat":"F","sv":"Vägnummer","en":"","svText":"Vägnummer anges endast för vägar i nummergruppen 1-499. Ett märke med streckad bård anger att vägen leder till den väg som vägvisas med det nummer som anges på märket.","enText":"","tip":"","kw":[],"img":"F14-1","variants":[{"key":"F14-2","en":""},{"key":"F14-3","en":""},{"key":"F14-4","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/vagnummer/","related":[]},{"id":"F15","cat":"F","sv":"Omledning","en":"","svText":"Märket anger permanent omledningsväg för ordinarie numrerad väg. Avvikelse från färg får inte ske.","enText":"","tip":"","kw":[],"img":"F15-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/omledning/","related":[]},{"id":"F16","cat":"F","sv":"Ökning av antal körfält","en":"","svText":"Märket anger att antalet körfält ökar. Märket är anpassat efter förhållandena på platsen. Symboler för fordonsslag, vägnummer eller fysisk avgränsning mellan motriktade körfält kan vara infogade i märket. Märket används även som förberedande upplysning om att antalet körfält ökar. Avståndet anges då på en tilläggstavla. Vid tillfällig trafikomläggning får märket utföras på orange botten. I övrigt får avvikelse från färg inte ske.","enText":"","tip":"","kw":[],"img":"F16-1","variants":[{"key":"F16-2","en":""},{"key":"F16-3","en":""},{"key":"F16-4","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/okning-av-antal-korfalt/","related":[]},{"id":"F17","cat":"F","sv":"Minskning av antal körfält","en":"","svText":"Märket anger att antalet körfält minskar. Märket är anpassat efter förhållandena på platsen. Märket används även som förberedande upplysning om att antalet körfält minskar. Avståndet anges då på en tilläggstavla. Vid tillfällig trafikomläggning får märket utföras på orange botten. I övrigt får avvikelse från färg inte ske.","enText":"","tip":"","kw":[],"img":"F17-1","variants":[{"key":"F17-2","en":""},{"key":"F17-3","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/minskning-av-antal-korfalt/","related":[]},{"id":"F18","cat":"F","sv":"Körfältsindelning på sträcka","en":"","svText":"Märket anger körriktning i körfält. Märket är anpassat efter förhållandena på platsen. Symboler för fordonsslag, vägnummer eller fysisk avgränsning mellan motriktade körfält kan vara infogade i märket. Märket används även som förberedande upplysning om att körfält börjar. Avståndet anges då på en tilläggstavla. Vid tillfällig trafikomläggning kan märket vara utfört med orange botten. I övrigt får avvikelse från färg inte ske.","enText":"","tip":"","kw":[],"img":"F18-1","variants":[{"key":"F18-2","en":""},{"key":"F18-3","en":""},{"key":"F18-4","en":""},{"key":"F18-5","en":""},{"key":"F18-6","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/korfaltsindelning-pa-stracka/","related":[]},{"id":"F19","cat":"F","sv":"Väganslutning med accelerationsfält","en":"","svText":"Märket är anpassat efter förhållandena på platsen. Vid tillfällig trafikomläggning kan märket vara utfört med orange botten. I övrigt får avvikelse från färg inte ske.","enText":"","tip":"","kw":[],"img":"F19-1","variants":[{"key":"F19-2","en":""},{"key":"F19-3","en":""},{"key":"F19-4","en":""},{"key":"F19-5","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/vaganslutning-med-accelerationsfalt/","related":[]},{"id":"F20","cat":"F","sv":"Väganslutning med separat körfält","en":"","svText":"Märket är anpassat efter förhållandena på platsen. Vid tillfällig trafikomläggning kan märket vara utfört med orange botten. I övrigt får avvikelse från färg inte ske.","enText":"","tip":"","kw":[],"img":"F20-1","variants":[{"key":"F20-2","en":""},{"key":"F20-3","en":""},{"key":"F20-4","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/vaganslutning-med-separat-korfalt/","related":[]},{"id":"F21","cat":"F","sv":"Körfältsindelning före korsning","en":"","svText":"Märket visar lämpligt körfält för fortsatt färd. Märket är anpassat till förhållandena på platsen. Avvikelse från färg får inte ske.","enText":"","tip":"","kw":[],"img":"F21-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/korfaltsindelning-fore-korsning/","related":[]},{"id":"F22","cat":"F","sv":"Riksmärke","en":"","svText":"Märket anger gräns till Sverige eller annat EU-land. Avvikelser från färg får inte ske.","enText":"","tip":"","kw":[],"img":"F22-2","variants":[{"key":"F22-1","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/riksmarke/","related":[]},{"id":"F23","cat":"F","sv":"Orienteringstavla för omledningsväg","en":"","svText":"Märket anger omledningsväg när ordinarie väg tillfälligt är avstängd. Avvikelse från färg får inte ske.","enText":"","tip":"","kw":[],"img":"F23-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/orienteringstavla-for-omledningsvag/","related":[]},{"id":"F24","cat":"F","sv":"Färdriktning vid omledning","en":"","svText":"Märket anger färdriktning vid tillfällig omledning av trafik. Avvikelse från färg får inte ske.","enText":"","tip":"","kw":[],"img":"F24-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/fardriktning-vid-omledning/","related":[]},{"id":"F25","cat":"F","sv":"Körfält upphör","en":"","svText":"Märket anger att ett körfält tillfälligt är avstängt och att ett annat körfält kan användas i färdriktningen. Märket är anpassat efter förhållandena på platsen. Avvikelse från färg får inte ske.","enText":"","tip":"","kw":[],"img":"F25-1","variants":[{"key":"F25-3","en":""},{"key":"F25-4","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/korfalt-upphor/","related":[]},{"id":"F26","cat":"F","sv":"Körfält avstängt","en":"","svText":"Märket anger att ett körfält tillfälligt är avstängt och att inget annat körfält i färdriktningen kan användas. Märket är anpassat efter förhållandena på platsen. Avvikelse från färg får inte ske.","enText":"","tip":"","kw":[],"img":"F26-1","variants":[{"key":"F26-2","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/korfalt-avstangt/","related":[]},{"id":"F27","cat":"F","sv":"Trafikplatsnummer","en":"","svText":"Märket anger numret på trafikplatsen. Märket kan vara kompletterat med avfartens beteckning. Avvikelse från färg får inte ske.","enText":"","tip":"","kw":[],"img":"F27-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/trafikplatsnummer/","related":[]},{"id":"F28","cat":"F","sv":"Parkeringshus","en":"","svText":"Upplysning om att parkeringsplatsen är fullbelagd eller om att det finns lediga platser kan lämnas i anslutning till märket. Parkeringshusets namn kan vara infogat i märket.","enText":"","tip":"","kw":[],"img":"F28-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/parkeringshus/","related":[]},{"id":"F29","cat":"F","sv":"Infartsparkering","en":"","svText":"Märket anger parkeringsplats i anslutning till kollektivtrafik. Symbolen på märket anger vilken typ av kollektivtrafik som är tillgänglig. Transportstyrelsen får meddela föreskrifter om vilka andra symboler som får användas. Parkeringsplatsens namn kan vara infogat i märket. Avvikelse från färg får inte ske.","enText":"","tip":"","kw":[],"img":"F29-1","variants":[{"key":"F29-2","en":""},{"key":"F29-3","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/infartsparkering/","related":[]},{"id":"F30","cat":"F","sv":"Lokal slinga","en":"","svText":"Märket anger ringväg eller motsvarande. Märket kan vara kompletterat med beteckning eller motsvarande. Avvikelse från färg får inte ske.","enText":"","tip":"","kw":[],"img":"F30-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/lokal-slinga/","related":[]},{"id":"F31","cat":"F","sv":"Lämplig väg eller förbifart för visst fordonsslag eller trafikantgrupp","en":"","svText":"Fordonsslaget eller trafikantgruppen anges med symbol enligt 28 §.","enText":"","tip":"","kw":[],"img":"F31-1","variants":[{"key":"F31-2","en":""},{"key":"F31-3","en":""},{"key":"F31-4","en":""},{"key":"F31-5","en":""},{"key":"F31-6","en":""},{"key":"F31-7","en":""},{"key":"F31-8","en":""},{"key":"F31-9","en":""},{"key":"F31-10","en":""},{"key":"F31-11","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/lamplig-vag-eller-forbifart-for-visst-fordonsslag-eller-trafikantgrupp/","related":[]},{"id":"F31a","cat":"F","sv":"Färdväg för långa fordonståg","en":"","svText":"Märket anger färdväg för långa fordonståg enligt föreskrifter meddelade med stöd av 4 kap. 17 f § trafikförordningen (1998:1276). Avvikelse från färg får inte ske.","enText":"","tip":"","kw":[],"img":"F31A","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/fardvag-for-langa-fordonstag/","related":[]},{"id":"F32","cat":"F","sv":"Farligt gods","en":"","svText":"Märket anger rekommenderad färdväg för fordon med last som omfattas av krav på märkning med orangefärgad skylt enligt föreskrifter som har meddelats med stöd av lagen (2006:263) om transport av farligt gods. Avvikelse från färg får inte ske.","enText":"","tip":"","kw":[],"img":"F32-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/farligt-gods/","related":[]},{"id":"F33","cat":"F","sv":"Räddningsplats","en":"","svText":"Märket anger en räddningsplats vid vägarbeten eller motsvarande. Siffran anger räddningsplatsens nummer. Avvikelse från färg får inte ske.","enText":"","tip":"","kw":[],"img":"F33-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/raddningsplats/","related":[]},{"id":"F34","cat":"F","gc":true,"sv":"Vägvisare","en":"","svText":"Märket anger väg till en ort, plats, anläggning eller liknande. Avstånd i kilometer kan anges. Andra symboler kan förekomma på märket. Transportstyrelsen får meddela föreskrifter om vilka symboler som får förekomma. Transportstyrelsen får också meddela föreskrifter om att det inte behöver förekomma någon symbol på märket.","enText":"","tip":"","kw":[],"img":"F34-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-gang-och-cykeltrafik/vagvisare/","related":[]},{"id":"F35","cat":"F","gc":true,"sv":"Tabellvägvisare","en":"","svText":"Märket anger väg till orter, platser, anläggningar eller liknande. Avståndet anges i kilometer. Andra symboler kan förekomma på märket. Transportstyrelsen får meddela föreskrifter om vilka symboler som får förekomma. Transportstyrelsen får också meddela föreskrifter om att det inte behöver förekomma någon symbol på märket.","enText":"","tip":"","kw":[],"img":"F35-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-gang-och-cykeltrafik/tabellvagvisare/","related":[]},{"id":"F36","cat":"F","gc":true,"sv":"Platsmärke","en":"","svText":"Märket anger en ort eller annan plats av betydelse för orienteringen. Kommun-, stads- eller länsvapen kan vara infogat i märket.","enText":"","tip":"","kw":[],"img":"F36-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-gang-och-cykeltrafik/platsmarke/","related":[]},{"id":"F37","cat":"F","gc":true,"sv":"Avståndstavla","en":"","svText":"Märket anger avståndet till angivna orter, platser, anläggningar eller liknande. Avståndet anges i kilometer. Andra symboler kan förekomma på märket. Transportstyrelsen får meddela föreskrifter om vilka symboler som får förekomma. Transportstyrelsen får också meddela föreskrifter om att det inte behöver förekomma någon symbol på märket.","enText":"","tip":"","kw":[],"img":"F37-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-gang-och-cykeltrafik/avstandstavla/","related":[]},{"id":"F38","cat":"F","gc":true,"sv":"Cykelled","en":"","svText":"Märket anger en särskilt anordnad cykelled. Märkets färgsättning kan variera.","enText":"","tip":"","kw":[],"img":"F38-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-gang-och-cykeltrafik/cykelled/","related":[]},{"id":"G1","cat":"G","sv":"Post","en":"","svText":"Märket anger postombud där brev och pakethantering samt frimärksförsäljning erbjuds.","enText":"","tip":"","kw":[],"img":"G1-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/post/","related":[]},{"id":"G2","cat":"G","sv":"Hjälptelefon","en":"","svText":"","enText":"","tip":"","kw":[],"img":"G2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/hjalptelefon/","related":[]},{"id":"G3","cat":"G","sv":"Radiostation för vägtrafikinformation","en":"","svText":"Märket anger att vägtrafikinformation ges regelbundet i återkommande sändningar som är avsedda att täcka ett större område.","enText":"","tip":"","kw":[],"img":"G3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/radiostation-for-vagtrafikinformation/","related":[]},{"id":"G4","cat":"G","sv":"Akutsjukhus","en":"","svText":"Märket anger ett sjukhus med akutmottagning.","enText":"","tip":"","kw":[],"img":"G4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/akutsjukhus/","related":[]},{"id":"G5","cat":"G","sv":"Industriområde","en":"","svText":"Märket anger ett område för industri eller annan liknande verksamhet.","enText":"","tip":"","kw":[],"img":"G5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/industriomrade/","related":[]},{"id":"G6","cat":"G","sv":"Järnvägsstation","en":"","svText":"","enText":"","tip":"","kw":[],"img":"G6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/jarnvagsstation/","related":[]},{"id":"G7","cat":"G","sv":"Busstation","en":"","svText":"Märket anger en busstation som utgör knutpunkt för flera busslinjer.","enText":"","tip":"","kw":[],"img":"G7","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/busstation/","related":[]},{"id":"G8","cat":"G","sv":"Flygplats","en":"","svText":"Märket anger en flygplats med reguljär flygtrafik.","enText":"","tip":"","kw":[],"img":"G8-1","variants":[{"key":"G8-2","en":""},{"key":"G8-3","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/flygplats/","related":[]},{"id":"G9","cat":"G","sv":"Brandsläckare","en":"","svText":"","enText":"","tip":"","kw":[],"img":"G9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/brandslackare/","related":[]},{"id":"G10","cat":"G","sv":"Handelsområde","en":"","svText":"Märket anger ett område för handel.","enText":"","tip":"","kw":[],"img":"G10","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/handelsomrade/","related":[]},{"id":"G11","cat":"G","sv":"Färja","en":"","svText":"Märket anger ett färjeläge eller att angivet färdmål nås med färja.","enText":"","tip":"","kw":[],"img":"G11","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/farja/","related":[]},{"id":"G12","cat":"G","sv":"Personfärja","en":"","svText":"Märket anger ett färjeläge för personfärja eller att angivet färdmål endast kan nås med färja avsedd för persontransport.","enText":"","tip":"","kw":[],"img":"G12","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/personfarja/","related":[]},{"id":"H1","cat":"H","sv":"Informationsplats","en":"","svText":"Märket anger en plats där det går att få information. Uppgift om vilken typ av information som finns kan anges i anslutning till märket.","enText":"","tip":"","kw":[],"img":"H1-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/informationsplats/","related":[]},{"id":"H2","cat":"H","sv":"Fordonsverkstad","en":"","svText":"","enText":"","tip":"","kw":[],"img":"H2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/fordonsverkstad/","related":[]},{"id":"H3","cat":"H","sv":"Drivmedel","en":"","svText":"Märket anger en anläggning som tillhandahåller drivmedel. Företagsemblem kan anges i anslutning till märket.","enText":"","tip":"","kw":[],"img":"H3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/drivmedel/","related":[]},{"id":"H4","cat":"H","sv":"Gas för fordonsdrift","en":"","svText":"Märket anger anläggningar som tillhandahåller olika typer av fordonsgas där typ av gas framgår av förkortningen i märket. Förkortningen CNG anger komprimerad naturgas. Transportstyrelsen får meddela föreskrifter om vilka andra förkortningar som får förekomma och vad de anger.","enText":"","tip":"","kw":[],"img":"H4-1","variants":[{"key":"H4-2","en":""},{"key":"H4-3","en":""},{"key":"H4-4","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/gas-for-fordonsdrift/","related":[]},{"id":"H5","cat":"H","sv":"Servering","en":"","svText":"Märket anger en anläggning som serverar drycker och enklare maträtter.","enText":"","tip":"","kw":[],"img":"H5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/servering/","related":[]},{"id":"H6","cat":"H","sv":"Restaurang","en":"","svText":"","enText":"","tip":"","kw":[],"img":"H6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/restaurang/","related":[]},{"id":"H7","cat":"H","sv":"Hotell","en":"","svText":"","enText":"","tip":"","kw":[],"img":"H7-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/hotell/","related":[]},{"id":"H8","cat":"H","sv":"Vandrarhem","en":"","svText":"","enText":"","tip":"","kw":[],"img":"H8-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/vandrarhem/","related":[]},{"id":"H9","cat":"H","sv":"Stugby","en":"","svText":"Märket anger en anläggning med ett större antal stugor.","enText":"","tip":"","kw":[],"img":"H9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/stugby/","related":[]},{"id":"H10","cat":"H","sv":"Stuga","en":"","svText":"Märket anger en anläggning med ett fåtal stugor.","enText":"","tip":"","kw":[],"img":"H10-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/stuga/","related":[]},{"id":"H11","cat":"H","sv":"Campingplats","en":"","svText":"Märket anger en anläggning som tillhandahåller platser för såväl tält som fordon med bostadsutrymme.","enText":"","tip":"","kw":[],"img":"H11-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/campingplats/","related":[]},{"id":"H12","cat":"H","sv":"Husvagnsplats","en":"","svText":"Märket anger en anläggning som enbart tillhandahåller platser för fordon med bostadsutrymme.","enText":"","tip":"","kw":[],"img":"H12-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/husvagnsplats/","related":[]},{"id":"H13","cat":"H","sv":"Rastplats","en":"","svText":"Märket anger en rastplats där det finns toalett som är tillgänglig även för rörelsehindrade.","enText":"","tip":"","kw":[],"img":"H13-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/rastplats/","related":[]},{"id":"H14","cat":"H","sv":"Toalett","en":"","svText":"Märket anger en toalett som är tillgänglig även för rörelsehindrade.","enText":"","tip":"","kw":[],"img":"H14-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/toalett/","related":[]},{"id":"H15","cat":"H","sv":"Badplats","en":"","svText":"Märket anger en badstrand eller annan badanläggning.","enText":"","tip":"","kw":[],"img":"H15-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/badplats/","related":[]},{"id":"H16","cat":"H","sv":"Friluftsområde","en":"","svText":"","enText":"","tip":"","kw":[],"img":"H16-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/friluftsomrade/","related":[]},{"id":"H17","cat":"H","sv":"Vandringsled","en":"","svText":"","enText":"","tip":"","kw":[],"img":"H17-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/vandringsled/","related":[]},{"id":"H18","cat":"H","sv":"Stollift","en":"","svText":"Märket anger en liftanläggning med stolar eller liknande.","enText":"","tip":"","kw":[],"img":"H18-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/stollift/","related":[]},{"id":"H19","cat":"H","sv":"Släplift","en":"","svText":"Märket anger en liftanläggning där skidåkare dras fram.","enText":"","tip":"","kw":[],"img":"H19-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/slaplift/","related":[]},{"id":"H20","cat":"H","sv":"Golfbana","en":"","svText":"","enText":"","tip":"","kw":[],"img":"H20-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/golfbana/","related":[]},{"id":"H21","cat":"H","sv":"Försäljningsställe för fiskekort","en":"","svText":"","enText":"","tip":"","kw":[],"img":"H21-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/forsaljningsstalle-for-fiskekort/","related":[]},{"id":"H22","cat":"H","sv":"Sevärdhet","en":"","svText":"Märket anger en sevärdhet av nationellt intresse. Sevärdhetens art anges i anslutning till märket.","enText":"","tip":"","kw":[],"img":"H22-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/sevardhet/","related":[]},{"id":"H23","cat":"H","sv":"Förberedande upplysning om vägnära service","en":"","svText":"Märket anger vägnära serviceanläggningar samt i vissa fall namn på dessa. Symbol för serviceanläggningarna drivmedel, restaurang och hotell kan vara kompletterade med företagsemblem eller företagsnamn. På märket anges avståndet till aktuell avfart eller korsning.","enText":"","tip":"","kw":[],"img":"H23","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/forberedande-upplysning-om-vagnara-service/","related":[]},{"id":"H24","cat":"H","sv":"Rum och frukost","en":"","svText":"Märket anger en anläggning som tillhandahåller rum för övernattning och frukost.","enText":"","tip":"","kw":[],"img":"H24-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/rum-och-frukost/","related":[]},{"id":"H25","cat":"H","sv":"Gårdsbutik","en":"","svText":"Märket anger en anläggning med försäljning av lokalt tillverkade eller närodlade produkter.","enText":"","tip":"","kw":[],"img":"H25","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/gardsbutik/","related":[]},{"id":"H26","cat":"H","sv":"Hantverk","en":"","svText":"Märket anger en anläggning med tillverkning och försäljning av hantverksprodukter.","enText":"","tip":"","kw":[],"img":"H26","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/hantverk/","related":[]},{"id":"H27","cat":"H","sv":"Laddstation","en":"","svText":"Märket anger en anläggning för extern laddning med elektrisk energi för fordons framdrivning.","enText":"","tip":"","kw":[],"img":"H27","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/laddstation/","related":[]},{"id":"H28","cat":"H","sv":"Anläggning som tillhandahåller platser för bilar med bostadsutrymme","en":"","svText":"Märket anger en anläggning som enbart tillhandahåller platser för bilar med bostadsutrymme.","enText":"","tip":"","kw":[],"img":"H28","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/anlaggning-tillhandahaller-plats-for-bil-med-bostadsutrymme/","related":[]},{"id":"I1","cat":"I","sv":"Turistväg","en":"","svText":"Märket anger en väg eller vägsträckning av turistiskt intresse. Märket kan vara infogat i ett lokaliseringsmärke för vägvisning.","enText":"","tip":"","kw":[],"img":"I1-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-turistiskt-intressanta-mal-med-mera/turistvag/","related":[]},{"id":"I2","cat":"I","sv":"Turistområde","en":"","svText":"Symbolen på märket är anpassad till temat för turistområdet. Symbolen kan vara infogad i ett lokaliseringsmärke för vägvisning. Transportstyrelsen får meddela föreskrifter om vilka symboler som får användas.","enText":"","tip":"","kw":[],"img":"I2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-turistiskt-intressanta-mal-med-mera/turistomrade/","related":[]},{"id":"I3","cat":"I","sv":"Landmärke","en":"","svText":"Märket upplyser om ett landmärke av turistiskt intresse som kan ses från vägen. Symbolen på märket visar en siluett av platsen. Transportstyrelsen får meddela föreskrifter om vilka symboler som får användas.","enText":"","tip":"","kw":[],"img":"I3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-turistiskt-intressanta-mal-med-mera/landmarke/","related":[]},{"id":"I4","cat":"I","sv":"Världsarv","en":"","svText":"Märket anger ett av UNESCO beslutat världsarv. Märket kan vara infogat i ett lokaliseringsmärke för vägvisning.","enText":"","tip":"","kw":[],"img":"I4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-turistiskt-intressanta-mal-med-mera/varldsarv/","related":[]},{"id":"J2","cat":"J","sv":"Upplysningsmärke","en":"","svText":"Märket ger upplysning av väsentligt intresse för framkomlighet eller säkerhet som inte kan ges på annat sätt. Varnings- eller förbudsmärke och lokaliseringsmärkena F14, vägnummer, och F15, omledning, kan vara infogade som förberedande upplysning. Upplysning med versal och gemen text kan förekomma.","enText":"","tip":"","kw":[],"img":"J2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/upplysningsmarken/upplysningsmarke/","related":[]},{"id":"J3","cat":"J","sv":"Livsfarlig ledning","en":"","svText":"Märket anger att det finns en elektrisk ledning över vägen eller leden som kan innebära fara.","enText":"","tip":"","kw":[],"img":"J3-1","variants":[{"key":"J3-2","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/upplysningsmarken/livsfarlig-ledning/","related":[]},{"id":"M1","cat":"M","sv":"Mittlinje eller körfältslinje","en":"","svText":"Mittlinje anger gränsen mellan körfält avsedda för färd i motsatta färdriktningar. Körfältslinje anger gränsen mellan körfält för färd i samma riktning. Markeringen har längdförhållandet 1:3 eller 1:1 mellan dellinje och mellanrum. Mittlinje kan även ange en cykelbanas mitt och har då längdförhållandet 1:1 mellan dellinje och mellanrum.","enText":"","tip":"","kw":[],"img":"M1-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/mittlinje-eller-korfaltslinje/","related":[]},{"id":"M2","cat":"M","sv":"Kantlinje","en":"","svText":"Markeringen anger en körbanas yttre gräns. Markeringen har längdförhållandet 1:2 mellan dellinje och mellanrum.","enText":"","tip":"","kw":[],"img":"M2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/kantlinje/","related":[]},{"id":"M3","cat":"M","sv":"Varningslinje","en":"","svText":"Varningslinje används för att informera om att linjen är olämplig att överskrida på grund av trafikförhållandena. Markeringen anger gränsen mellan körfält avsedda för färd i motsatta färdriktningar. Markeringen kan även användas för att upplysa om en kommande heldragen linje. Markeringen har längdförhållandet 3:1 mellan dellinje och mellanrum.","enText":"","tip":"","kw":[],"img":"M3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/varningslinje/","related":[]},{"id":"M4","cat":"M","sv":"Ledlinje","en":"","svText":"Markeringen anger lämplig färdväg för trafik i komplicerade korsningar. Markeringen används även i andra fall där det finns behov av ledning. Markeringen har längdförhållandet 1:1 mellan dellinje och mellanrum.","enText":"","tip":"","kw":[],"img":"M4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/ledlinje/","related":[]},{"id":"M5","cat":"M","sv":"Cykelfältslinje","en":"","svText":"Markeringen anger gränsen mellan ett cykelfält och ett annat körfält. Markeringen har längdförhållandet 1:1 mellan dellinje och mellanrum.","enText":"","tip":"","kw":[],"img":"M5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/cykelfaltslinje/","related":[]},{"id":"M6","cat":"M","sv":"Linje för fordon i linjetrafik med flera","en":"","svText":"","enText":"","tip":"","kw":[],"img":"M6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/linje-for-fordon-i-linjetrafik-med-flera/","related":[]},{"id":"M7","cat":"M","sv":"Reversibelt körfält","en":"","svText":"Markeringen avgränsar körfält som upplåts för trafik omväxlande i den ena och i den andra färdriktningen. Markeringen har längdförhållandet 1:1 mellan dellinje och mellanrum.","enText":"","tip":"","kw":[],"img":"M7-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/reversibelt-korfalt/","related":[]},{"id":"M8","cat":"M","sv":"Heldragen linje","en":"","svText":"Markeringen anger att bestämmelserna i 3 kap. 11 § eller 12 § tredje stycket trafikförordningen (1998:1276) eller föreskrifter meddelade med stöd av den förordningen är tillämpliga. Heldragen linje kan vara heldragen mittlinje, heldragen körfältslinje eller heldragen kantlinje. Heldragen körfältslinje och heldragen kantlinje är enkel. Heldragen mittlinje kan vara såväl enkel som dubbel.","enText":"","tip":"","kw":[],"img":"M8-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/heldragen-linje/","related":[]},{"id":"M9","cat":"M","sv":"Spärrområde","en":"","svText":"Markeringen anger ett område där fordon inte får föras enligt 3 kap. 11 § trafikförordningen. Markeringen består av vinklade eller snedställda streck beroende på förhållandena på platsen. Del av eller hela området kan utföras i vitt.","enText":"","tip":"","kw":[],"img":"M9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/sparromrade/","related":[]},{"id":"M10","cat":"M","sv":"Mittlinje eller körfältslinje och heldragen linje","en":"","svText":"Markeringen används där det inte är tillåtet för fordon som befinner sig på samma sida som den heldragna linjen att byta körfält.","enText":"","tip":"","kw":[],"img":"M10-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/mittlinje-eller-korfaltslinje-och-heldragen-linje/","related":[]},{"id":"M11","cat":"M","sv":"Varningslinje och heldragen linje","en":"","svText":"Markeringen används där det inte är tillåtet för fordon som befinner sig på samma sida som den heldragna linjen att byta körfält.","enText":"","tip":"","kw":[],"img":"M11-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/varningslinje-och-heldragen-linje/","related":[]},{"id":"M12","cat":"M","sv":"Mittlinje och varningslinje","en":"","svText":"Markeringen används där det är olämpligt att överskrida varningslinjen på grund av trafikförhållandena.","enText":"","tip":"","kw":[],"img":"M12-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/mittlinje-och-varningslinje/","related":[]},{"id":"M13","cat":"M","sv":"Stopplinje","en":"","svText":"Markeringen anger var ett fordon ska stannas enligt ett vägmärke, en trafiksignal eller Y1, ljussignal.","enText":"","tip":"","kw":[],"img":"M13-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/stopplinje/","related":[]},{"id":"M14","cat":"M","sv":"Väjningslinje","en":"","svText":"Markeringen anger den linje som fordon inte bör passera när föraren iakttar väjningsplikt.","enText":"","tip":"","kw":[],"img":"M14-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/vajningslinje/","related":[]},{"id":"M15","cat":"M","sv":"Övergångsställe","en":"","svText":"Markeringen anger ett övergångsställe och är utförd där märke B3, övergångsställe, är uppsatt.","enText":"","tip":"","kw":[],"img":"M15-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/overgangsstalle/","related":[]},{"id":"M16","cat":"M","sv":"Cykelpassage eller cykelöverfart","en":"","svText":"Markeringen anger en cykelpassage eller en cykelöverfart där märke B8, cykelöverfart, är uppsatt. Om markeringen avser en cykelöverfart ska den kombineras med markeringen M14, väjningslinje. Markeringen M15, övergångsställe, får utgöra en av begränsningslinjerna till en cykelpassage eller en cykelöverfart.","enText":"","tip":"","kw":[],"img":"M16-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/cykelpassage-eller-cykeloverfart/","related":[]},{"id":"M17","cat":"M","sv":"Farthinder","en":"","svText":"Markeringen anger ett farthinder i form av gupp, grop eller liknande.","enText":"","tip":"","kw":[],"img":"M17-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/farthinder/","related":[]},{"id":"M17a","cat":"M","sv":"Cykelbox","en":"","svText":"Markeringen anger lämplig placering för cyklande och förare av moped klass II. Markeringen får anpassas efter förhållandena på platsen.","enText":"","tip":"","kw":[],"img":"M17A-CYKELBOX","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/cykelbox/","related":[]},{"id":"M18","cat":"M","sv":"Förberedande upplysning om väjningsplikt eller stopplikt","en":"","svText":"Markeringen anger att väjningsplikt eller stopplikt gäller längre fram i färdriktningen.","enText":"","tip":"","kw":[],"img":"M18-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/forberedande-upplysning-om-vajningsplikt-eller-stopplikt/","related":[]},{"id":"M19","cat":"M","sv":"Körfältspilar","en":"","svText":"Markeringen upplyser, för närmaste korsning, lämpligt körfält för fortsatt färd. Är körfältet avgränsat med heldragen körfältslinje ska förare följa den eller de riktningar som pilen visar. Detta gäller dock inte förare som i anslutning till korsningen färdas in i eller från ett reserverat körfält. Körfältspil med två pilangivelser i samma riktning upplyser om lämpligt körfält för fortsatt färd i närmaste och därpå följande korsning. Markeringarna upplyser också om att fordon inte får föras i motsatt riktning.","enText":"","tip":"","kw":[],"img":"M19-1","variants":[{"key":"M19A","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/korfaltspilar/","related":[]},{"id":"M20","cat":"M","sv":"Körfältsbyte","en":"","svText":"Markeringen anger att körfältsbyte snarast måste ske.","enText":"","tip":"","kw":[],"img":"M20-1","variants":[{"key":"M20A","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/korfaltsbyte/","related":[]},{"id":"M21","cat":"M","sv":"Förbud mot att stanna och parkera","en":"","svText":"Markeringen upplyser om förbud mot att stanna och parkera fordon och är placerad i körbanans kant. Avvikelse från färg får inte ske.","enText":"","tip":"","kw":[],"img":"M21-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/forbud-mot-att-stanna-och-parkera/","related":[]},{"id":"M22","cat":"M","sv":"Förbud mot att parkera","en":"","svText":"Markeringen upplyser om förbud mot att parkera fordon och är placerad i körbanans kant. Markeringen upplyser även om utsträckning av busshållplats. Markeringen har längdförhållandet 1:1 mellan dellinje och mellanrum. Avvikelse från färg får inte ske.","enText":"","tip":"","kw":[],"img":"M22-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/forbud-mot-att-parkera/","related":[]},{"id":"M23","cat":"M","sv":"Förbud mot att stanna och parkera eller att parkera","en":"","svText":"Markeringen används som förstärkning av markeringarna M21, förbud mot att stanna och parkera, och M22, förbud mot att parkera. Avvikelse från färg får inte ske.","enText":"","tip":"","kw":[],"img":"M23-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/forbud-mot-att-stanna-och-parkera-eller-att-parkera/","related":[]},{"id":"M24","cat":"M","sv":"Uppställningsplats","en":"","svText":"Markeringen anger gränsen för uppställningsplats för fordon. Markeringen kan vara utförd med bruten linje.","enText":"","tip":"","kw":[],"img":"M24-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/uppstallningsplats/","related":[]},{"id":"M25","cat":"M","sv":"Gång- och cykelpil","en":"","svText":"Markeringen visar lämplig färdväg för gående eller cyklande och förare av moped klass II.","enText":"","tip":"","kw":[],"img":"M25-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/gang--och-cykelpil/","related":[]},{"id":"M26","cat":"M","sv":"Cykel","en":"","svText":"Markeringen visar bana eller lämplig färdväg för cyklande och förare av moped klass II.","enText":"","tip":"","kw":[],"img":"M26-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/cykel/","related":[]},{"id":"M27","cat":"M","sv":"Gående","en":"","svText":"Markeringen visar bana eller lämplig färdväg för gående.","enText":"","tip":"","kw":[],"img":"M27-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/gaende/","related":[]},{"id":"M28","cat":"M","sv":"Buss","en":"","svText":"Markeringen visar att körfältet är avsett för fordon i linjetrafik med flera.","enText":"","tip":"","kw":[],"img":"M28-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/buss/","related":[]},{"id":"M29","cat":"M","sv":"Hastighet","en":"","svText":"Markeringen upplyser om högsta tillåtna hastighet.","enText":"","tip":"","kw":[],"img":"M29-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/hastighet/","related":[]},{"id":"M30","cat":"M","sv":"Vägnummer","en":"","svText":"Markeringen upplyser om vägnummer.","enText":"","tip":"","kw":[],"img":"M30","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/vagnummer/","related":[]},{"id":"M31","cat":"M","sv":"Ändamålsplats","en":"","svText":"Markeringen upplyser om en uppställningsplats som är avsedd för ett visst ändamål. Texten anpassas efter ändamålet.","enText":"","tip":"","kw":[],"img":"M31-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/andamalsplats/","related":[]},{"id":"M32","cat":"M","sv":"Stopp","en":"","svText":"Markeringen upplyser om stopplikt. Markeringen används tillsammans med märke B2, stopplikt, för att förstärka anvisningen.","enText":"","tip":"","kw":[],"img":"M32-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/stopp/","related":[]},{"id":"M33","cat":"M","sv":"Rörelsehindrad","en":"","svText":"Markeringen upplyser om uppställningsplats endast för rörelsehindrade.","enText":"","tip":"","kw":[],"img":"M33-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/rorelsehindrad/","related":[]},{"id":"M34","cat":"M","sv":"Information","en":"","svText":"Markeringen ger upplysning, varning eller vägledning av vikt för trafikanten.","enText":"","tip":"","kw":[],"img":"M34-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/information/","related":[]},{"id":"P1","cat":"P","sv":"Stopp","en":"","svText":"Tecknet anger stopp för den trafikant som kommer framifrån eller bakifrån. Tecknet används i vägkorsning och gäller så länge polismannen vänder sig åt samma håll. För trafikanter som kommer från sidan betyder tecknet att vägen är fri och att det är tillåtet att köra. Tecknet får ges i kombination med tecken P2, stopp. Tecknet kan ges med en stoppspade.","enText":"","tip":"","kw":[],"img":"P1-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-polisman-med-flera/stopp/","related":[]},{"id":"P2","cat":"P","sv":"Stopp","en":"","svText":"Tecknet anger stopp för den trafikant som handflatan är vänd mot. Tecknet kan ges med en stoppspade.","enText":"","tip":"","kw":[],"img":"P2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-polisman-med-flera/stopp1/","related":[]},{"id":"P3","cat":"P","sv":"Stopp","en":"","svText":"Tecknet anger stopp för den trafikant som lyktan är vänd mot. Tecknet används under mörker och vid nedsatt sikt. Lyktan hålls i den position där den lättast uppfattas av trafikanter.","enText":"","tip":"","kw":[],"img":"P3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-polisman-med-flera/stopp2/","related":[]},{"id":"P4","cat":"P","sv":"Kör fram","en":"","svText":"Tecknet anger att trafikanter i den färdriktning som tecknet ges får fortsätta framåt. Tecknet ges med en vinkande rörelse i färdriktningen.","enText":"","tip":"","kw":[],"img":"P4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-polisman-med-flera/kor-fram/","related":[]},{"id":"P5","cat":"P","sv":"Minska hastigheten","en":"","svText":"Tecknet anger att den trafikant som polismannen är vänd mot ska minska hastigheten. Under mörker och vid nedsatt sikt kan tecknet vara förtydligat med en lykta som visar vitt eller gult ljus eller en reflexanordning som återkastar vitt eller gult ljus.","enText":"","tip":"","kw":[],"img":"P5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-polisman-med-flera/minska-hastigheten/","related":[]},{"id":"P6","cat":"P","sv":"Kontroll","en":"","svText":"Tecknet anger att fordonsförare ska köra in på kontrollplats för kontroll. Visas symbol för visst eller vissa slag av fordon enligt 2 kap. 28 § gäller skyldigheten att köra in för kontroll endast för förare av dessa fordon. Tecknet är anpassat till förhållandena på platsen.","enText":"","tip":"","kw":[],"img":"P6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-polisman-med-flera/kontroll/","related":[]},{"id":"P7","cat":"P","sv":"Förberedande upplysning om kontroll","en":"","svText":"Tecknet ger förberedande upplysning om kontroll. Tecknet är anpassat till förhållandena på platsen.","enText":"","tip":"","kw":[],"img":"P7-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-polisman-med-flera/forberedande-upplysning-om-kontroll/","related":[]},{"id":"P8","cat":"P","sv":"Minska hastigheten","en":"","svText":"Tecknet anger att de trafikanter som befinner sig bakom polisfordonet ska minska hastigheten. Under mörker och vid nedsatt sikt får tecknet förtydligas med en lykta som visar vitt eller gult ljus eller en reflexanordning som återkastar vitt eller gult ljus.","enText":"","tip":"","kw":[],"img":"P8-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-polisman-med-flera/minska-hastigheten1/","related":[]},{"id":"P9","cat":"P","sv":"Minska hastigheten","en":"","svText":"Tecknet anger att de trafikanter som möter polisfordonet ska minska hastigheten. Under mörker och vid nedsatt sikt får tecknet förtydligas med en lykta som visar vitt eller gult ljus eller en reflexanordning som återkastar vitt eller gult ljus.","enText":"","tip":"","kw":[],"img":"P9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-polisman-med-flera/minska-hastigheten2/","related":[]},{"id":"P10","cat":"P","sv":"Följ efter och stanna bakom polisfordonet när detta stannar","en":"","svText":"Tecknet anger att föraren av det fordon som befinner sig bakom polisfordonet ska följa efter det och stanna när polisfordonet stannar. Tecknet kan ges med en stoppspade.","enText":"","tip":"","kw":[],"img":"P10-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-polisman-med-flera/folj-efter-och-stanna-bakom-polisfordonet-nar-detta-stannar/","related":[]},{"id":"P11","cat":"P","sv":"Kör in till vägkanten och stanna framför polisfordonet","en":"","svText":"Tecknet anger att föraren av det fordon som befinner sig framför polisfordonet ska köra in till vägkanten och stanna. Tecknet ges med växelvis blinkande blått och rött ljus.","enText":"","tip":"","kw":[],"img":"P11-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-polisman-med-flera/kor-in-till-vagkanten-och-stanna-framfor-polisfordonet/","related":[]},{"id":"S1","cat":"S","sv":"Tung lastbil","en":"","svText":"","enText":"","tip":"","kw":[],"img":"S1-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/tung-lastbil/","related":[]},{"id":"S2","cat":"S","sv":"Tung lastbil med tillkopplad släpvagn","en":"","svText":"","enText":"","tip":"","kw":[],"img":"S2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/tung-lastbil-med-tillkopplad-slapvagn/","related":[]},{"id":"S3","cat":"S","sv":"Personbil","en":"","svText":"","enText":"","tip":"","kw":[],"img":"S3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/personbil/","related":[]},{"id":"S4","cat":"S","sv":"Personbil med tillkopplad släpkärra","en":"","svText":"","enText":"","tip":"","kw":[],"img":"S4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/personbil-med-tillkopplad-slapkarra/","related":[]},{"id":"S5","cat":"S","sv":"Buss","en":"","svText":"","enText":"","tip":"","kw":[],"img":"S5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/buss/","related":[]},{"id":"S6","cat":"S","sv":"Traktor och motorredskap klass II","en":"","svText":"","enText":"","tip":"","kw":[],"img":"S6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/traktor-och-motorredskap-klass-ii/","related":[]},{"id":"S7","cat":"S","sv":"Motorcykel","en":"","svText":"Symbolen anger tvåhjulig motorcykel utan sidvagn och tvåhjulig moped klass I utan sidvagn.","enText":"","tip":"","kw":[],"img":"S7-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/motorcykel/","related":[]},{"id":"S8","cat":"S","sv":"Cykel och moped klass II","en":"","svText":"","enText":"","tip":"","kw":[],"img":"S8-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/cykel-och-moped-klass-ii/","related":[]},{"id":"S9","cat":"S","sv":"Släpkärra","en":"","svText":"","enText":"","tip":"","kw":[],"img":"S9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/slapkarra/","related":[]},{"id":"S10","cat":"S","sv":"Gående","en":"","svText":"","enText":"","tip":"","kw":[],"img":"S10-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/gaende/","related":[]},{"id":"S11","cat":"S","sv":"Rörelsehindrade","en":"","svText":"","enText":"","tip":"","kw":[],"img":"S11-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/rorelsehindrade/","related":[]},{"id":"S12","cat":"S","sv":"Personbil klass II","en":"","svText":"","enText":"","tip":"","kw":[],"img":"S12-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/personbil-klass-ii/","related":[]},{"id":"S13","cat":"S","sv":"Personfärja","en":"","svText":"Symbolen anger ett färjeläge för personfärja eller att angivet färdmål endast kan nås med färja avsedd för persontransport.","enText":"","tip":"","kw":[],"img":"S13-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/personfarja/","related":[]},{"id":"T1","cat":"T","sv":"Vägsträckas längd","en":"","svText":"Tavlan anger början och slutet på en vägsträcka.","enText":"","tip":"","kw":[],"img":"T1-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/vagstrackas-langd/","related":[]},{"id":"T2","cat":"T","sv":"Avstånd","en":"","svText":"Tavlan anger avståndet till det som vägmärket avser.","enText":"","tip":"","kw":[],"img":"T2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/avstand/","related":[]},{"id":"T3","cat":"T","sv":"Avstånd till stopplikt","en":"","svText":"Tavlan används endast under märke B1, väjningsplikt.","enText":"","tip":"","kw":[],"img":"T3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/avstand-till-stopplikt/","related":[]},{"id":"T4","cat":"T","sv":"Fri bredd","en":"","svText":"","enText":"","tip":"","kw":[],"img":"T4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/fri-bredd/","related":[]},{"id":"T5","cat":"T","sv":"Totalvikt","en":"","svText":"Tavlan anger att angivelsen på märket gäller fordon med en totalvikt som överstiger det angivna värdet.","enText":"","tip":"","kw":[],"img":"T5","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/totalvikt/","related":[]},{"id":"T6","cat":"T","sv":"Tidsangivelse","en":"","svText":"Tavlan anger när angivelsen på vägmärket gäller. Används klockslag i kombination med andra villkor anger tavlan även när dessa villkor gäller. Svarta eller vita siffror utan parentes avser vardagar utom vardag före sön- och helgdag. Svarta eller vita siffror inom parentes avser vardag före sön- och helgdag. Röda siffror avser sön- och helgdag. Om angivelsen sträcker sig över midnatt gäller tidsperioden efter midnatt påföljande dag. Anges viss dag eller viss veckodag gäller regleringen denna dag oavsett om dagen är en vardag, söndag eller helgdag.","enText":"","tip":"","kw":[],"img":"T6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/tidsangivelse/","related":[]},{"id":"T7","cat":"T","sv":"Rörelsehindrade","en":"","svText":"Tavlan anger att angivelsen på märket gäller den som får parkera enligt ett parkeringstillstånd som avses i 13 kap. 8 eller 9 § trafikförordningen. Tavlan används endast under märke E19, parkering. Anges tid med tavla T6, tidsangivelse, gäller den kompletterande anvisningen enligt de närmare föreskrifterna till tavlan T6, tidsangivelse.","enText":"","tip":"","kw":[],"img":"T7","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/rorelsehindrade/","related":[]},{"id":"T8","cat":"T","sv":"Symboltavla","en":"","svText":"Tavlan anger att det märke som tavlan är uppsatt under endast gäller för det fordonsslag eller den trafikantgrupp som anges på tavlan. Fordonsslaget eller trafikantgruppen anges med symbol enligt 28 §. Anges tid enligt tavla T6, tidsangivelse, gäller den kompletterande anvisningen enligt de närmare föreskrifterna till tavlan T6, tidsangivelse.","enText":"","tip":"","kw":[],"img":"T8-1","variants":[{"key":"T8-2","en":""},{"key":"T8-3","en":""},{"key":"T8-4","en":""},{"key":"T8-5","en":""},{"key":"T8-6","en":""},{"key":"T8-7","en":""},{"key":"T8-8","en":""},{"key":"T8-9","en":""},{"key":"T8-10","en":""},{"key":"T8-11","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/symboltavla/","related":[]},{"id":"T9","cat":"T","sv":"Nedsatt syn","en":"","svText":"Tavlan anger att personer med nedsatt syn är vanligt förekommande.","enText":"","tip":"","kw":[],"img":"T9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/nedsatt-syn/","related":[]},{"id":"T10","cat":"T","sv":"Nedsatt hörsel","en":"","svText":"Tavlan anger att personer med nedsatt hörsel är vanligt förekommande. Tavlan har alltid gul bottenfärg.","enText":"","tip":"","kw":[],"img":"T10","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/nedsatt-horsel/","related":[]},{"id":"T11","cat":"T","sv":"Utsträckning","en":"","svText":"Tavlan med dubbelriktade pilar, uppsatt vågrätt eller lodrätt, anger att angivelsen gäller på båda sidor av märket. Tavlan med nedåtriktad pil anger att angivelsen slutar. Tavlan med höger- eller vänsterriktad pil visar att angivelsen gäller åt det håll pilen visar. Används tavlan under märke E19, parkering, har den svarta tecken på vit botten utan bård. Tavlorna kan även användas fristående för att ange avgränsning av uppställningsplatser på ett område, om det vid infarten till området anges att parkering är tillåten.","enText":"","tip":"","kw":[],"img":"T11-1","variants":[{"key":"T11-2","en":""},{"key":"T11-3","en":""},{"key":"T11-4","en":""},{"key":"T11-5","en":""},{"key":"T11-6","en":""},{"key":"T11-7","en":""},{"key":"T11-8","en":""},{"key":"T11-9","en":""},{"key":"T11-10","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/utstrackning/","related":[]},{"id":"T12","cat":"T","sv":"Riktning","en":"","svText":"Tavlan anger riktning till angivelsen på märket.","enText":"","tip":"","kw":[],"img":"T12-1","variants":[{"key":"T12-2","en":""},{"key":"T12-3","en":""},{"key":"T12-4","en":""},{"key":"T12-5","en":""},{"key":"T12-6","en":""},{"key":"T12-7","en":""},{"key":"T12-8","en":""},{"key":"T12-9","en":""},{"key":"T12-10","en":""},{"key":"T12-11","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/t12-riktning/","related":[]},{"id":"T13","cat":"T","sv":"Flervägsväjning","en":"","svText":"Tavlan anger att förare på samtliga tillfarter i en korsning har väjningsplikt.","enText":"","tip":"","kw":[],"img":"T13-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/flervagsvajning/","related":[]},{"id":"T14","cat":"T","sv":"Flervägsstopp","en":"","svText":"Tavlan anger att förare på samtliga tillfarter i en korsning har stopplikt.","enText":"","tip":"","kw":[],"img":"T14-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/flervagsstopp/","related":[]},{"id":"T15","cat":"T","sv":"Vägars fortsättning i korsning","en":"","svText":"Tavlan anger en korsning där förare på en väg som anges med smalt streck har väjningsplikt mot fordon på en väg som anges med brett streck. Symbolen är anpassad efter förhållandena på platsen.","enText":"","tip":"","kw":[],"img":"T15-1","variants":[{"key":"T15-2","en":""},{"key":"T15-3","en":""},{"key":"T15-4","en":""},{"key":"T15-5","en":""},{"key":"T15-6","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/vagars-fortsattning-i-korsning/","related":[]},{"id":"T16","cat":"T","sv":"Avgift","en":"","svText":"Tavlan anger att avgift ska betalas för parkering enligt den taxa som anges på en parkeringsmätare, biljettautomat eller motsvarande och att övriga villkor för parkering som anges där ska iakttas. Anges tid enligt tavla T6, tidsangivelse, gäller den kompletterande anvisningen enligt de närmare föreskrifterna till tavlan T6, tidsangivelse.","enText":"","tip":"","kw":[],"img":"T16","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/avgift/","related":[]},{"id":"T17","cat":"T","sv":"Parkeringsskiva","en":"","svText":"Tavlan anger att tiden när parkering påbörjats ska anges med en parkeringsskiva eller motsvarande. Anges tid enligt tavla T6, tidsangivelse, gäller den kompletterande anvisningen enligt de närmare föreskrifterna till tavlan T6, tidsangivelse.","enText":"","tip":"","kw":[],"img":"T17-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/parkeringsskiva/","related":[]},{"id":"T18","cat":"T","sv":"Tillåten tid för parkering","en":"","svText":"Tavlan anger längsta tillåten tid för parkering. Anges tid enligt tavla T6, tidsangivelse, gäller den kompletterande anvisningen enligt de närmare föreskrifterna till tavlan T6, tidsangivelse.","enText":"","tip":"","kw":[],"img":"T18","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/tillaten-tid-for-parkering/","related":[]},{"id":"T19","cat":"T","sv":"Boende","en":"","svText":"Tavlan anger att boende i ett område, med särskilt tillstånd, får parkera enligt särskilda villkor. Texten kan vara kompletterad med områdesbeteckning eller motsvarande. Anges tid enligt tavla T6, tidsangivelse, gäller den kompletterande anvisningen enligt de närmare föreskrifterna till tavlan T6, tidsangivelse.","enText":"","tip":"","kw":[],"img":"T19","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/boende/","related":[]},{"id":"T20","cat":"T","sv":"Parkeringsbiljett","en":"","svText":"Tavlan anger att parkering är avgiftsfri men att parkeringsbiljett ska användas vid parkering. Anges tid enligt tavla T6, tidsangivelse, gäller den kompletterande anvisningen enligt de närmare föreskrifterna till tavlan T6, tidsangivelse.","enText":"","tip":"","kw":[],"img":"T20","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/parkeringsbiljett/","related":[]},{"id":"T21","cat":"T","sv":"Uppställning av fordon","en":"","svText":"Tavlan anger hur fordon ska ställas upp på en parkeringsplats. Tavlan är anpassad efter förhållandena på platsen.","enText":"","tip":"","kw":[],"img":"T21-1","variants":[{"key":"T21-2","en":""},{"key":"T21-3","en":""},{"key":"T21-4","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/uppstallning-av-fordon/","related":[]},{"id":"T22","cat":"T","sv":"Text","en":"","svText":"Tavlan ger kompletterande anvisning som inte kan ges med någon annan tilläggstavla eller kombinationer av dessa. Anges tid enligt tavla T6, tidsangivelse, gäller den kompletterande anvisningen enligt de närmare föreskrifterna till tavlan T6, tidsangivelse.","enText":"","tip":"","kw":[],"img":"T22-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/text/","related":[]},{"id":"T23","cat":"T","sv":"Tunnelkategori","en":"","svText":"Tavlan används under märke C9, förbud mot trafik med fordon lastat med farligt gods. Bokstaven B, C, D eller E anger tunnelns kategori. Klockslag kan anges på tavlan enligt de närmare föreskrifterna till tilläggstavla T6, tidsangivelse.","enText":"","tip":"","kw":[],"img":"T23-1","variants":[{"key":"T23-2","en":""},{"key":"T23-3","en":""},{"key":"T23-4","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/tunnelkategori/","related":[]},{"id":"T24","cat":"T","sv":"Laddplats","en":"","svText":"Tavlan anger en plats för extern laddning av elektricitet för fordons framdrivning. Tavlan används under märke E19, parkering, och anger att endast fordon med möjlighet till extern laddning av elektricitet för fordonets framdrivning får parkera.","enText":"","tip":"","kw":[],"img":"T24-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/laddplats/","related":[]},{"id":"T25","cat":"T","sv":"Öppet dygnet runt","en":"","svText":"Tavlan anger att en servering eller restaurang är öppen dygnet runt. Tavlan används under något av märkena H5, servering, eller H6, restaurang.","enText":"","tip":"","kw":[],"img":"T25-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/oppet-dygnet-runt/","related":[]},{"id":"SIG1","cat":"SIG","sv":"Röd","en":"","svText":"Stopp. Fordon får inte passera stopplinjen eller, om sådan saknas, signalen. Signal med konturpil gäller endast den eller de färdriktningar som anges med pilen.","enText":"","tip":"","kw":[],"img":"SIG1-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/rod/","related":[]},{"id":"SIG2","cat":"SIG","sv":"Röd + gul","en":"","svText":"Växling till grön signalbild är omedelbart förestående. I övrigt har signalbilden samma innebörd som röd.","enText":"","tip":"","kw":[],"img":"SIG2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/rod--gul/","related":[]},{"id":"SIG3","cat":"SIG","sv":"Grön","en":"","svText":"Fordon får fortsätta framåt. Grön pil innebär att signalen gäller den färdriktning som anges med pilen. Fordon får föras i pilens riktning även om en annan signalbild visas samtidigt.","enText":"","tip":"","kw":[],"img":"SIG3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/gron/","related":[]},{"id":"SIG4","cat":"SIG","sv":"Gul","en":"","svText":"Stanna. Fordon får inte passera stopplinjen eller, om sådan saknas, signalen i annat fall än då det hunnit så långt fram när signalbilden växlar från grön till gul att det inte kan stannas utan fara. Signal med konturpil gäller endast den eller de färdriktningar som anges med pilen.","enText":"","tip":"","kw":[],"img":"SIG4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/gul/","related":[]},{"id":"SIG5","cat":"SIG","sv":"Blinkande gul","en":"","svText":"Särskild försiktighet ska iakttas vid passage.","enText":"","tip":"","kw":[],"img":"SIG5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/blinkande-gul/","related":[]},{"id":"SIG6","cat":"SIG","sv":"Röd akustisk signal med långsam pulsfrekvens","en":"","svText":"Förbjudet att beträda en körbana, cykelbana eller järnvägs- eller spårvägskorsning. Gående som befinner sig på körbanan eller cykelbanan när signalen slår om till röd signalbild skall fortsätta till andra sidan. Finns en refug eller liknande anordning skall den gående dock stanna där.","enText":"","tip":"","kw":[],"img":"SIG6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/rod-akustisk-signal-med-langsam-pulsfrekvens/","related":[]},{"id":"SIG7","cat":"SIG","sv":"Grön akustisk signal med snabb pulsfrekvens","en":"","svText":"Körbana, cykelbana eller järnvägs- eller spårvägskorsning får beträdas.","enText":"","tip":"","kw":[],"img":"SIG7-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/gron-akustisk-signal-med-snabb-pulsfrekvens/","related":[]},{"id":"SIG8","cat":"SIG","sv":"S","en":"","svText":"Stopp. Fordon och spårvagn får inte passera stopplinjen, eller om sådan saknas, signalen.","enText":"","tip":"","kw":[],"img":"SIG8-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/s/","related":[]},{"id":"SIG9","cat":"SIG","sv":"S+vågrätt streck","en":"","svText":"Växling till lodrätt streck är omedelbart förestående. I övrigt har signalbilden samma innebörd som S.","enText":"","tip":"","kw":[],"img":"SIG9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/svagratt-streck/","related":[]},{"id":"SIG10","cat":"SIG","sv":"Lodrätt streck eller pil","en":"","svText":"Fordon och spårvagn får fortsätta framåt. Pil innebär att signalen gäller den färdriktning som anges med pilen.","enText":"","tip":"","kw":[],"img":"SIG10-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/lodratt-streck-eller-pil/","related":[]},{"id":"SIG11","cat":"SIG","sv":"Vågrätt streck","en":"","svText":"Stanna. Fordon och spårvagn får inte passera stopplinjen, eller om sådan saknas, signalen i annat fall än då det hunnit så långt fram när signalen växlar från lodrätt till vågrätt streck att det inte kan stannas utan fara.","enText":"","tip":"","kw":[],"img":"SIG11-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/vagratt-streck/","related":[]},{"id":"SIG12","cat":"SIG","sv":"Rött kryss","en":"","svText":"Körfältet och i förekommande fall vägrenen intill körfältet får inte användas för trafik.","enText":"","tip":"","kw":[],"img":"SIG12-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/rott-kryss/","related":[]},{"id":"SIG13","cat":"SIG","sv":"Gul pil eller pilar","en":"","svText":"Föraren skall byta körfält i den riktning pilen eller pilarna anger.","enText":"","tip":"","kw":[],"img":"SIG13-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/gul-pil-eller-pilar/","related":[]},{"id":"SIG14","cat":"SIG","sv":"Grön pil","en":"","svText":"Körfältet får användas för trafik. I stället för grön pil kan ett vägmärke förekomma.","enText":"","tip":"","kw":[],"img":"SIG14-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/gron-pil/","related":[]},{"id":"SIG16","cat":"SIG","sv":"Rött blinkande ljus","en":"","svText":"Stopp. Trafikanter får inte passera stopplinjen eller, om sådan saknas, signalen.","enText":"","tip":"","kw":[],"img":"SIG16-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/rott-blinkande-ljus2/","related":[]},{"id":"SIG17","cat":"SIG","sv":"Rött fast ljus","en":"","svText":"Signalen anger att en väg är helt avstängd.","enText":"","tip":"","kw":[],"img":"SIG17-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/rott-fast-ljus/","related":[]},{"id":"SIG18","cat":"SIG","sv":"Gult blinkande ljus för påkallande av särskild försiktighet","en":"","svText":"Signalen används där en väg är delvis avstängd eller för att det ska vara lättare att upptäcka ett vägmärke eller en annan anordning. Antalet ljusöppningar och deras placering är anpassade till den anordning signalen är placerad vid. Signalen kan användas fristående eller tillsammans med en anordning som avger ljud för att ge anvisning för gående om korsande spårvagn eller buss.","enText":"","tip":"","kw":[],"img":"SIG18-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/gult-blinkande-ljus-for-pakallande-av-sarskild-forsiktighet/","related":[]},{"id":"V1","cat":"V","sv":"Stopp","en":"","svText":"Tecknet anger stopp för den trafikant vakten är vänd mot. Under mörker ges tecknet med lykta med rött ljus. Tecknet får också ges med märke C34, stopp för angivet ändamål, med texten Vakt.","enText":"","tip":"","kw":[],"img":"V1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-vakt/stopp/","related":[]},{"id":"V2","cat":"V","sv":"Kör fram","en":"","svText":"Tecknet anger att trafikanten får fortsätta framåt. Tecknet ges med en vinkande rörelse i färdriktningen.","enText":"","tip":"","kw":[],"img":"V2","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-vakt/kor-fram/","related":[]},{"id":"V3","cat":"V","sv":"Kännetecken","en":"","svText":"Kännetecken ska bäras både framtill och baktill.","enText":"","tip":"","kw":[],"img":"V3","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-vakt/kannetecken/","related":[]},{"id":"X1","cat":"X","sv":"Markeringspil","en":"","svText":"Anordningen anger att fordonsförare måste svänga kraftigt i den gula pilens eller de gula pilarnas riktning på grund av till exempel en kurva. Antalet pilar är anpassat till förhållandena på platsen. Om anordningen används vid ett vägarbete eller tillfälligt av någon annan anledning har den röd botten.","enText":"","tip":"","kw":[],"img":"X1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/andra-anordningar-for-anvisningar-for-trafiken/markeringspil/","related":[]},{"id":"X2","cat":"X","sv":"Markeringsskärm för hinder","en":"","svText":"Anordningen anger att framkomligheten på vägen är inskränkt på grund av ett hinder. Anordningen kan även ange att en väg är helt eller delvis avstängd för trafik. Antalet gula fält är anpassat till hindret eller till förhållandena på platsen. Om anordningen används vid ett vägarbete eller tillfälligt av någon annan anledning har den röd botten.","enText":"","tip":"","kw":[],"img":"X2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/andra-anordningar-for-anvisningar-for-trafiken/markeringsskarm-for-hinder/","related":[]},{"id":"X3","cat":"X","sv":"Markeringsskärm för sidohinder, farthinder med mera","en":"","svText":"Anordningen anger vägens eller körbanans kant eller skiljer trafikriktningar åt vid komplicerade passager. Anordningen anger även att fordon ska föras på den sida som de gula fälten lutar ned mot. Om anordningen används vid ett vägarbete eller tillfälligt av någon annan anledning har den röd botten. De gula fälten kan då vara vågräta. Fordonen får då föras på båda sidor om anordningen.","enText":"","tip":"","kw":[],"img":"X3-1","variants":[{"key":"X3-2","en":""},{"key":"X3-3","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/andra-anordningar-for-anvisningar-for-trafiken/markeringsskarm-for-sidohinder-farthinder-mm/","related":[]},{"id":"X4","cat":"X","sv":"Avfartsskärm","en":"","svText":"Anordningen anger skiljepunkten mellan en huvudkörbana och en avfart där det finns ett retardationsfält.","enText":"","tip":"","kw":[],"img":"X4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/andra-anordningar-for-anvisningar-for-trafiken/avfartsskarm/","related":[]},{"id":"X5","cat":"X","sv":"Gul ljuspil eller ljuspilar","en":"","svText":"Anordningen anger att trafikanter ska passera på den sida pilen eller pilarna visar. Pilen eller pilarna kan vara blinkande.","enText":"","tip":"","kw":[],"img":"X5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/andra-anordningar-for-anvisningar-for-trafiken/gul-ljuspil-eller-ljuspilar/","related":[]},{"id":"X6","cat":"X","sv":"Särskild varningsanordning","en":"","svText":"Anordningen anger att framkomligheten på en väg är inskränkt på grund av ett tillfälligt hinder eller liknande. Texten på anordningen anpassas till orsaken.","enText":"","tip":"","kw":[],"img":"X6-1","variants":[{"key":"X6-2","en":""},{"key":"X6-3","en":""},{"key":"X6-4","en":""},{"key":"X6-5","en":""},{"key":"X6-6","en":""}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/andra-anordningar-for-anvisningar-for-trafiken/sarskild-varningsanordning/","related":[]},{"id":"X7","cat":"X","sv":"Vägbom","en":"","svText":"Anordningen anger att en väg är helt eller delvis avstängd för trafik. En bom kan vara försedd med ytterligare anordningar för att öka synbarheten.","enText":"","tip":"","kw":[],"img":"X7-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/andra-anordningar-for-anvisningar-for-trafiken/vagbom/","related":[]},{"id":"X8","cat":"X","sv":"Tillfällig stängning","en":"","svText":"Anordningen anger att en anvisning genom ett vägmärke om väg till ort, plats, inrättning, anläggning eller liknande tillfälligt inte gäller. Anordningen är anpassad till vägmärket.","enText":"","tip":"","kw":[],"img":"X8-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/andra-anordningar-for-anvisningar-for-trafiken/x8/","related":[]},{"id":"X9","cat":"X","sv":"Cirkulationstrafik","en":"","svText":"Anordningen anger mittpunkten i en rondell runt vilken fordon ska föras.","enText":"","tip":"","kw":[],"img":"X9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/andra-anordningar-for-anvisningar-for-trafiken/cirkulationstrafik/","related":[]},{"id":"X10","cat":"X","sv":"Stolpmarkeringsanordning","en":"","svText":"Anordningen används för att det ska vara lättare att upptäcka ett vägmärke eller en annan anordning enligt denna förordning. Anordningen är placerad på en stolpe eller motsvarande som bär upp ett vägmärke eller en annan anordning. Anordningen är anpassad till förhållandena på platsen. En stolpmarkeringsanordning har samma färgsättning som det vägmärke eller den andra anordning som den sitter under om inte Transportstyrelsen föreskriver annat.","enText":"","tip":"","kw":[],"img":"X10","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/andra-anordningar-for-anvisningar-for-trafiken/stolpmarkeringsanordning/","related":[]},{"id":"Y1","cat":"Y","sv":"Rött blinkande ljus","en":"","svText":"Stopp. Trafikanter får inte passera stopplinjen eller, om sådan saknas, signalen. Ljussignalen består av två ljusöppningar på samma höjd som avger växelvis blinkande rött ljus och en skärm i form av en triangel med rundade hörn och med spetsen nedåt. Skärmen kan vara försedd med vit bård. Under de röda ljusöppningarna kan det finnas en cirkulär ljusöppning, från vilken det kan avges blinkande vitt ljus för att göra korsningen lättare att upptäcka.","enText":"","tip":"","kw":[],"img":"Y1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/sakerhetsanordningar-i-korsningar-med-jarnvag-eller-sparvag/rott-blinkande-ljus/","related":[]},{"id":"Y2","cat":"Y","sv":"Ljudsignal","en":"","svText":"","enText":"","tip":"","kw":[],"img":"Y2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/sakerhetsanordningar-i-korsningar-med-jarnvag-eller-sparvag/ljudsignal/","related":[]},{"id":"Y3","cat":"Y","sv":"Bom","en":"","svText":"Anordningens baksida får förses med texten ”Kör genom bommen”.","enText":"","tip":"","kw":[],"img":"Y3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/sakerhetsanordningar-i-korsningar-med-jarnvag-eller-sparvag/bom/","related":[]},{"id":"Y4","cat":"Y","sv":"Plankorsningsskärm","en":"","svText":"Skärmen används för att göra en plankorsning lättare att upptäcka. Skärmen är anpassad till förhållandena på platsen och kan vara liggande.","enText":"","tip":"","kw":[],"img":"Y4","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/sakerhetsanordningar-i-korsningar-med-jarnvag-eller-sparvag/plankorsningsskarm/","related":[]}];
